INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l74','out of the limelight','',NULL,'/aʊt əv ðə ˈlaɪmlaɪt/','The old star now lives out of the limelight.','这位老明星如今远离公众视线地生活。','After retiring, she stayed out of the limelight.','退休后,她一直不再抛头露面。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l74','get on with it','',NULL,'/ɡet ɑːn wɪð ɪt/','Please get on with it somewhere else.','请到别处继续(做)吧。','Stop chatting and get on with your work.','别聊了,接着干你的活。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l74','get through to sb','',NULL,'/ɡet θruː tə/','The director got through to the park office.','导演打通了公园办公室的电话。','I tried to call, but I couldn''t get through to her.','我打了电话,但一直没能接通她。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l74','too good to be true','',NULL,'/tuː ɡʊd tə bi truː/','The disguise was too good to be true.','这化装好得让人不敢相信。','A free trip? That sounds too good to be true.','免费旅行?那听起来好得不像真的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp1','choice','{"stem":"\"Look! Some famous actors ___ a movie in the park right now.\"(此刻正在做:现在进行时)","options":["have filmed","film","are filming","filmed"],"answer_index":2,"stem_cn":"看!一些名演员此刻正在公园里拍电影。","explanation_cn":"“此刻正在做”用现在进行时 = am/is/are + doing。✓ Some famous actors are filming a movie right now. ✗ film:一般现在,表经常;✗ filmed:一般过去;✗ have filmed:现在完成,表已拍完。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp1','choice','{"stem":"\"They ___ costumes and heavy disguises at the moment.\"(此刻正穿着:现在进行时)","options":["wore","wears","wear","are wearing"],"answer_index":3,"stem_cn":"他们此刻正穿着戏服、化着浓妆。","explanation_cn":"“此刻正穿着”用现在进行时。✓ They are wearing costumes at the moment. ✗ wear:一般现在;✗ wore:一般过去;✗ wears:一般现在第三人称单数。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp1','choice','{"stem":"\"Be quiet — the director ___ to the actors now.\"(此刻正在说:现在进行时)","options":["is talking","talks","talked","talk"],"answer_index":0,"stem_cn":"安静——导演正在跟演员讲话。","explanation_cn":"“此刻正在说”用现在进行时。✓ The director is talking to the actors now. ✗ talks:一般现在;✗ talked:一般过去;✗ talk:原形。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp2','choice','{"stem":"\"This director ___ a new movie every year.\"(每年都拍,经常:一般现在时)","options":["make","is making","makes","made"],"answer_index":2,"stem_cn":"这位导演每年都拍一部新电影。","explanation_cn":"“每年都拍(经常发生)”用一般现在时。✓ This director makes a new movie every year. ✗ is making:进行时表此刻;✗ made:一般过去;✗ make:第三人称单数要加 s。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp2','choice','{"stem":"\"The director ___ the scene to look real, so he sends them into the crowd.\"(想要,一般现在)","options":["wants","wanted","want","is wanting"],"answer_index":0,"stem_cn":"导演想让这一幕显得真实,就把他们送进人群。","explanation_cn":"want(想要)表状态,且此处是普遍情况,用一般现在时。✓ The director wants the scene to look real. ✗ is wanting:状态动词不用进行时;✗ wanted:一般过去;✗ want:第三人称单数要加 s。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp2','choice','{"stem":"\"Every morning the crew ___ at eight and starts work.\"(每天早上,经常:一般现在)","options":["is arriving","arrives","arrive","arrived"],"answer_index":1,"stem_cn":"每天早上,剧组八点到,然后开工。","explanation_cn":"“每天早上到(经常)”用一般现在时。✓ Every morning the crew arrives at eight. ✗ is arriving:进行时表此刻;✗ arrived:一般过去;✗ arrive:第三人称单数要加 s。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp3','choice','{"stem":"\"I ___ that actor — he is very famous.\"(认识=状态,不用进行时)","options":["have been knowing","was knowing","am knowing","know"],"answer_index":3,"stem_cn":"我认识那个演员,他很有名。","explanation_cn":"know(认识、知道)表状态,不用进行时,用一般现在。✓ I know that actor. ✗ am knowing:状态动词不用进行时;✗ was knowing:同理不用进行;✗ have been knowing:状态动词不用完成进行。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp3','choice','{"stem":"\"The worker doesn''t ___ them, even close up.\"(认出=状态,不用进行时)","options":["recognize","recognizing","to recognizing","be recognizing"],"answer_index":0,"stem_cn":"那工人连近看都认不出他们。","explanation_cn":"recognize(认出)表状态,doesn''t 后接原形。✓ The worker doesn''t recognize them. ✗ recognizing:不接 -ing;✗ be recognizing:状态动词不用进行;✗ to recognizing:形式错。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp3','choice','{"stem":"\"She ___ nervous before the scene begins.\"(显得=状态,不用进行时)","options":["was seeming","seems","is seeming","seem"],"answer_index":1,"stem_cn":"这一幕开始前,她显得很紧张。","explanation_cn":"seem(显得)表状态,不用进行时,用一般现在。✓ She seems nervous before the scene begins. ✗ is seeming:状态动词不用进行;✗ was seeming:同理;✗ seem:第三人称单数要加 s。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp4','choice','{"stem":"\"The worker asked them to get ___ of the flower beds.\"(从…出来、离开)","options":["out","on","over","in"],"answer_index":0,"stem_cn":"工人让他们从花坛里出去。","explanation_cn":"“从…里出去、离开”用 get out (of)。✓ get out of the flower beds. ✗ in:是“进入”;✗ over:是“克服”;✗ on:构不成“离开”。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp4','choice','{"stem":"\"I''ve lost my key, so I can''t get ___ my trailer.\"(进入)","options":["out of","over","into","off"],"answer_index":2,"stem_cn":"我把钥匙丢了,进不了自己的拖车。","explanation_cn":"“进入(某空间)”用 get into。✓ I can''t get into my trailer. ✗ out of:是“离开”;✗ over:是“克服”;✗ off:是“下来”。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp4','choice','{"stem":"\"It took the actor a week to get ___ his cold.\"(从…中恢复、克服)","options":["off","over","into","out"],"answer_index":1,"stem_cn":"那演员花了一周才从感冒中恢复。","explanation_cn":"“从(病)中恢复、克服”用 get over。✓ It took him a week to get over his cold. ✗ out:构不成“恢复”;✗ into:是“进入”;✗ off:是“下来”。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp5','choice','{"stem":"\"He''s hard to work with; I can''t get ___ him.\"(与…相处融洽)","options":["on with","out of","into","off"],"answer_index":0,"stem_cn":"他很难合作,我跟他处不来。","explanation_cn":"“与(某人)相处融洽、合得来”用 get on with sb。✓ I can''t get on with him. ✗ off:是“下来/脱身”;✗ into:是“进入”;✗ out of:是“离开”。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp5','choice','{"stem":"\"Please get ___ the grass and film somewhere else.\"(从…下来、离开)","options":["on","into","off","over"],"answer_index":2,"stem_cn":"请从草坪上下来,到别处去拍。","explanation_cn":"“从(草坪等)下来、离开”用 get off。✓ Please get off the grass. ✗ on:是“上去”;✗ over:是“克服”;✗ into:是“进入”。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp5','choice','{"stem":"\"Finally the director ___ to the park office on the phone.\"(打通、接通)","options":["got into","got through","got over","got off"],"answer_index":1,"stem_cn":"最后导演终于打通了公园办公室的电话。","explanation_cn":"“(打电话)打通、接通”用 get through (to)。✓ The director got through to the park office. ✗ got off:下车/脱身;✗ got into:进入;✗ got over:克服。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp6','choice','{"stem":"\"The disguise was so good that no one ___ the actors.\"(认出用哪个词)","options":["forgot","ignored","remembered","recognized"],"answer_index":3,"stem_cn":"化装太好了,没人认出这些演员。","explanation_cn":"“认出”用 recognize。✓ No one recognized the actors. ✗ remembered:是“记得”;✗ forgot:是“忘记”;✗ ignored:是“忽视、不理”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp6','choice','{"stem":"\"They wore heavy makeup and costumes as a ___.\"(伪装用哪个词)","options":["disguise","mistake","vacation","reward"],"answer_index":0,"stem_cn":"他们化浓妆、穿戏服作为伪装。","explanation_cn":"“伪装、化装”用 disguise。✓ They wore heavy makeup and costumes as a disguise. ✗ reward:是“奖励”;✗ mistake:是“错误”;✗ vacation:是“假期”。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',5,'am2_l74_gp6','choice','{"stem":"\"They were ___ well disguised that the worker didn''t know them.\"(如此…以致:程度词)","options":["very","such","too","so"],"answer_index":3,"stem_cn":"他们化装得如此之好,以致工人都不认识他们。","explanation_cn":"后面接“well disguised(副词/形容词)”时,“如此…以致”用 so…that。✓ They were so well disguised that the worker didn''t know them. ✗ such:接名词短语;✗ too:是“太…以致不能”;✗ very:构不成“如此…以致”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',6,NULL,'choice','{"stem":"美语里\"电影\"常说:","options":["picture-show","screen-play","movie","film"],"answer_index":2,"explanation_cn":"美语“电影”说 movie;英式说 film。✓ They are filming a movie. 他们正在拍电影。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',6,NULL,'choice','{"stem":"美语里\"市中心\"常说:","options":["downtown","town-middle","city centre","central-city"],"answer_index":0,"explanation_cn":"美语“市中心”说 downtown;英式说 city centre。✓ We drove downtown to the theater. 我们开车去市中心的剧院。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',6,NULL,'choice','{"stem":"disguise 的意思是:","options":["奖励","邀请","伪装,化装","假期"],"answer_index":2,"explanation_cn":"disguise = 伪装、化装。✓ heavy disguises 浓重的化装。\n顺带记:奖励 = reward;邀请 = invitation;假期 = vacation."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',6,NULL,'choice','{"stem":"recognize 的意思是:","options":["隐藏","拒绝","忘记","认出"],"answer_index":3,"explanation_cn":"recognize = 认出。✓ no one recognizes them 没人认出他们。\n顺带记:忘记 = forget;拒绝 = refuse;隐藏 = hide."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',6,NULL,'choice','{"stem":"costume 的意思是:","options":["布景","剧本","戏服,服装","门票"],"answer_index":2,"explanation_cn":"costume = 戏服、服装。✓ fans in costume 穿着戏服的粉丝。\n顺带记:剧本 = script;门票 = ticket;布景 = set."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',6,NULL,'choice','{"stem":"famous 的意思是:","options":["廉价的","害羞的","陌生的","著名的"],"answer_index":3,"explanation_cn":"famous = 著名的。✓ some famous actors 一些名演员。\n顺带记:陌生的 = strange;廉价的 = cheap;害羞的 = shy."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',7,NULL,'cloze','{"stem":"第 1 空","context":"Some famous actors ___1___ a movie in the park today. They ___2___ costumes, so no one ___3___ them. When a worker told them to get ___4___ of the flower beds, he didn''t even believe they were actors.","blank_no":1,"options":["are filming","film","filmed","have filmed"],"answer_index":0,"explanation_cn":"“此刻正在拍”用现在进行时。✓ Some actors are filming a movie today.\n✗ film:一般现在;✗ filmed:一般过去;✗ have filmed:现在完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',7,NULL,'cloze','{"stem":"第 2 空","context":"Some famous actors ___1___ a movie in the park today. They ___2___ costumes, so no one ___3___ them. When a worker told them to get ___4___ of the flower beds, he didn''t even believe they were actors.","blank_no":2,"options":["are wearing","wear","wore","wears"],"answer_index":0,"explanation_cn":"“此刻正穿着”用现在进行时。✓ They are wearing costumes.\n✗ wear:一般现在;✗ wore:一般过去;✗ wears:第三人称单数一般现在。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',7,NULL,'cloze','{"stem":"第 3 空","context":"Some famous actors ___1___ a movie in the park today. They ___2___ costumes, so no one ___3___ them. When a worker told them to get ___4___ of the flower beds, he didn''t even believe they were actors.","blank_no":3,"options":["recognizes","is recognizing","recognized","recognize"],"answer_index":0,"explanation_cn":"recognize 表状态,此处“没人认出”用一般现在(no one 作单数)。✓ no one recognizes them.\n✗ is recognizing:状态动词不用进行;✗ recognized:一般过去;✗ recognize:no one 后要用单数 recognizes。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',7,NULL,'cloze','{"stem":"第 4 空","context":"Some famous actors ___1___ a movie in the park today. They ___2___ costumes, so no one ___3___ them. When a worker told them to get ___4___ of the flower beds, he didn''t even believe they were actors.","blank_no":4,"options":["out","in","over","off"],"answer_index":0,"explanation_cn":"“从…里出去”用 get out of。✓ get out of the flower beds.\n✗ in:进入;✗ over:克服;✗ off:下来。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',8,NULL,'choice','{"stem":"What are the famous actors doing in the park?","options":["Selling tickets","Watching a parade","Filming a movie in costume and disguise","Having a picnic with fans"],"answer_index":2,"explanation_cn":"课文说 Some famous actors are filming a movie in the park… wearing costumes and heavy disguises。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',8,NULL,'choice','{"stem":"Why didn''t the park worker recognize them?","options":["They kept their backs to him","Their disguises were so good that he thought they were fans in costume","They were standing far away","It was too dark to see"],"answer_index":1,"explanation_cn":"课文说 The actors are so well disguised that the worker doesn''t recognize them… he thinks they are just fans in costume。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',8,NULL,'choice','{"stem":"How was the problem finally solved?","options":["They gave up and went home","The worker called the police","The actors ran away","The director got through to the park office and sorted it out"],"answer_index":3,"explanation_cn":"课文说 Finally the director gets through to the park office and sorts everything out。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',9,NULL,'choice','{"stem":"你想说\"看!他们此刻正在公园里拍电影\"(现在进行时,此刻正在做):","options":["Look! They filmed a movie in the park right now.","Look! They film a movie in the park right now.","Look! They have filmed a movie in the park right now.","Look! They are filming a movie in the park right now."],"answer_index":3,"explanation_cn":"“此刻正在做”用现在进行时 are + doing。✓ Look! They are filming a movie right now. 场合:描述眼前正在发生的动作。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',9,NULL,'choice','{"stem":"你想说\"我认识那个演员\"(know 是表状态的词,不用进行时):","options":["I am knowing that actor.","I know that actor.","I was knowing that actor.","I have been knowing that actor."],"answer_index":1,"explanation_cn":"know 表状态,不用进行时,用一般现在。✓ I know that actor. 场合:说“我认识/知道某人某事”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',9,NULL,'choice','{"stem":"你想说\"请下草坪,到别处继续\"(get off / get on with):","options":["Please get off the grass and get on with it somewhere else.","Please get into the grass and get through it somewhere else.","Please get on the grass and get off it somewhere else.","Please get out the grass and get over it somewhere else."],"answer_index":0,"explanation_cn":"get off = 从(草坪)下来;get on with it = 到别处继续做。✓ Please get off the grass and get on with it somewhere else. 场合:请人离开某处、换地方接着做。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',10,NULL,'choice','{"stem":"disguise 的意思是:","options":["奖励","伪装,化装","邀请","假期"],"answer_index":1,"explanation_cn":"disguise = 伪装、化装。✓ heavy disguises 浓重的化装。\n顺带记:奖励 = reward;邀请 = invitation;假期 = vacation."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',10,NULL,'choice','{"stem":"recognize 的意思是:","options":["认出","忘记","隐藏","拒绝"],"answer_index":0,"explanation_cn":"recognize = 认出。✓ no one recognizes them 没人认出他们。\n顺带记:忘记 = forget;拒绝 = refuse;隐藏 = hide."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',10,NULL,'choice','{"stem":"\"Look! They ___ a movie right now.\"(此刻正在做:现在进行时)","options":["filmed","film","have filmed","are filming"],"answer_index":3,"stem_cn":"看!他们此刻正在拍电影。","explanation_cn":"“此刻正在做”用现在进行时。✓ They are filming a movie right now.\n✗ film:一般现在;✗ filmed:一般过去;✗ have filmed:现在完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',10,NULL,'choice','{"stem":"\"I ___ that actor very well.\"(认识=表状态,不用进行时)","options":["know","was knowing","am knowing","have been knowing"],"answer_index":0,"stem_cn":"我很熟悉那个演员。","explanation_cn":"know 表状态,不用进行时,用一般现在。✓ I know that actor very well.\n✗ am knowing / was knowing / have been knowing:状态动词都不用进行或完成进行。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',10,NULL,'choice','{"stem":"\"get through to the office\" 里 get through 的意思是:","options":["推倒办公室","(打电话)接通、打通","路过办公室","走出办公室"],"answer_index":1,"explanation_cn":"get through (to sb) = (打电话)接通、打通。如 The director got through to the office 导演打通了办公室的电话。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',10,NULL,'choice','{"stem":"\"out of the limelight\" 的意思是:","options":["走出剧院","灯坏了","不再受公众关注、远离聚光灯","关掉了灯"],"answer_index":2,"explanation_cn":"out of the limelight = 不再是公众注意的中心、远离聚光灯。如 The old star lives out of the limelight now。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',10,NULL,'choice','{"stem":"Why were the actors almost thrown out of the park?","options":["Their disguises were so perfect that the worker didn''t recognize them and thought they were fans","They damaged the flowers on purpose","They had not paid for tickets","They arrived after closing time"],"answer_index":0,"passage":"Some famous actors are filming a movie in the park today. They are wearing costumes and heavy disguises, so no one recognizes them. The director wants the scene to look real, so he tells them to walk among the crowd. \"This disguise is too perfect,\" one actor says. \"I don''t think anyone knows who we are.\" Just then, a park worker comes over and asks them to get out of the flower beds. \"You can''t film here,\" he says. \"Please get off the grass and get on with it somewhere else.\" The actors are so well disguised that the worker doesn''t recognize them at all. They try to explain, but he doesn''t believe them — he thinks they are just fans in costume. Finally the director gets through to the park office and sorts everything out. Everyone laughs: their disguises were so good that they almost got thrown out of their own movie!","explanation_cn":"课文说 The actors are so well disguised that the worker doesn''t recognize them… he thinks they are just fans in costume… they almost got thrown out of their own movie。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',10,NULL,'choice','{"stem":"What did the director do to solve the problem?","options":["He called the actors'' fans for help","He got through to the park office and sorted everything out","He argued with the worker for hours","He canceled the whole movie"],"answer_index":1,"passage":"Some famous actors are filming a movie in the park today. They are wearing costumes and heavy disguises, so no one recognizes them. The director wants the scene to look real, so he tells them to walk among the crowd. \"This disguise is too perfect,\" one actor says. \"I don''t think anyone knows who we are.\" Just then, a park worker comes over and asks them to get out of the flower beds. \"You can''t film here,\" he says. \"Please get off the grass and get on with it somewhere else.\" The actors are so well disguised that the worker doesn''t recognize them at all. They try to explain, but he doesn''t believe them — he thinks they are just fans in costume. Finally the director gets through to the park office and sorts everything out. Everyone laughs: their disguises were so good that they almost got thrown out of their own movie!","explanation_cn":"课文说 Finally the director gets through to the park office and sorts everything out。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',10,NULL,'choice','{"stem":"What were the actors wearing?","options":["Ordinary street clothes","Nothing unusual","Police uniforms","Costumes and heavy disguises"],"answer_index":3,"audio":"Some famous actors are filming a movie in the park today. They are wearing costumes and heavy disguises, so no one recognizes them. The director wants the scene to look real, so he tells them to walk among the crowd. \"This disguise is too perfect,\" one actor says. \"I don''t think anyone knows who we are.\" Just then, a park worker comes over and asks them to get out of the flower beds. \"You can''t film here,\" he says. \"Please get off the grass and get on with it somewhere else.\" The actors are so well disguised that the worker doesn''t recognize them at all. They try to explain, but he doesn''t believe them — he thinks they are just fans in costume. Finally the director gets through to the park office and sorts everything out. Everyone laughs: their disguises were so good that they almost got thrown out of their own movie!","explanation_cn":"课文说 They are wearing costumes and heavy disguises。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l74',10,NULL,'choice','{"stem":"Did anyone recognize the actors?","options":["No — not even the park worker","Yes — the park office manager","Yes — a whole crowd of fans","Yes — a newspaper reporter"],"answer_index":0,"audio":"Some famous actors are filming a movie in the park today. They are wearing costumes and heavy disguises, so no one recognizes them. The director wants the scene to look real, so he tells them to walk among the crowd. \"This disguise is too perfect,\" one actor says. \"I don''t think anyone knows who we are.\" Just then, a park worker comes over and asks them to get out of the flower beds. \"You can''t film here,\" he says. \"Please get off the grass and get on with it somewhere else.\" The actors are so well disguised that the worker doesn''t recognize them at all. They try to explain, but he doesn''t believe them — he thinks they are just fans in costume. Finally the director gets through to the park office and sorts everything out. Everyone laughs: their disguises were so good that they almost got thrown out of their own movie!","explanation_cn":"课文说 no one recognizes them… the worker doesn''t recognize them at all。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l75',2,10,75,'The Big Race','大比赛','KS3/27/51 一般过去时综合(教材 L75 Key structures,方案B换情节包):规则与不规则动词过去式(held/shone/came/ran/blew/shot/fell/took/won 与 entered/passed/handed/raced/shouted/crossed)、一般过去时叙事(过去连续动作)、过去时间状语(last Saturday/yesterday/two weeks ago)、否定与疑问(didn''t / Did…?)','上周六,我们学校举办了一年一度的运动会。阳光灿烂,几百个家庭前来观看。我们班报名参加了接力赛,我跑最后一棒。哨声一响,选手们猛冲向前。起初我们落后了,我以为我们没戏了。但我们的第三棒超过了另外两人,把接力棒交到了我手里。我深吸一口气,拼尽全力地跑。人群欢呼起来,我刚好领先其他人冲过了终点线。我们以半秒之差赢了!我根本没料到会赢。那是我们班有史以来最棒的一次运动会。','{"q":"Listen and answer — Did the writer''s class win the race?","options":["Yes — they won by half a second","No — they came in last","No — they didn''t finish","Yes — they won by a full minute"],"answer_index":0}'::jsonb,'{"title":"KS3/27/51 一般过去时综合","intro":"本课复习一般过去时(讲过去发生、已经结束的事):①规则动词加 -ed(enter→entered, race→raced);②不规则动词要单独记(hold→held, come→came, run→ran, shoot→shot, fall→fell, take→took, win→won);③叙述过去一连串动作,都用过去式;④过去时间状语:last Saturday、yesterday、two weeks ago;⑤否定与疑问借助 did:didn''t + 原形 / Did + 主语 + 原形。","table":{"headers":["类别","例子"],"rows":[["规则过去式 -ed","entered / passed / raced / shouted / crossed"],["不规则过去式","hold→held, come→came, run→ran, win→won"],["过去叙事(连续动作)","The whistle blew and the runners shot forward."],["过去时间状语","last Saturday / yesterday / two weeks ago"],["否定与疑问(did)","I didn''t expect it. / Did your class win?"]]},"specialRules":[{"rule":"美语里“足球”说 soccer(英式 football)、“运动鞋”说 sneakers(英式 trainers)、“体育课”说 gym class(英式 PE);本课已按美语写。","mark":"soccer/sneakers/gym"},{"rule":"一般过去的否定和疑问都靠 did:didn''t + 动词原形(didn''t expect)、Did + 主语 + 动词原形(Did your class win?),动词本身不再变过去式。","mark":"did / didn''t"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l75',1,NULL,'Last Saturday our school held its yearly sports day. The sun shone, and hundreds of families came to watch.','上周六,我们学校举办了一年一度的运动会。阳光灿烂,几百个家庭前来观看。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l75',2,NULL,'My class entered the relay race, and I ran the last leg. When the whistle blew, the runners shot forward.','我们班报名参加了接力赛,我跑最后一棒。哨声一响,选手们猛冲向前。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l75',3,NULL,'At first we fell behind, and I thought we had no chance. But our third runner passed two others and handed me the baton.','起初我们落后了,我以为我们没戏了。但我们的第三棒超过了另外两人,把接力棒交到了我手里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l75',4,NULL,'I took a deep breath and raced as fast as I could. The crowd shouted, and I crossed the line just ahead of the others.','我深吸一口气,拼尽全力地跑。人群欢呼起来,我刚好领先其他人冲过了终点线。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l75',5,NULL,'We won by half a second! I didn''t expect it at all. It was the best sports day our class ever had.','我们以半秒之差赢了!我根本没料到会赢。那是我们班有史以来最棒的一次运动会。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
