INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l75','take a deep breath','',NULL,'/teɪk ə diːp breθ/','I took a deep breath and raced.','我深吸一口气,然后开跑。','Take a deep breath and stay calm.','深吸一口气,保持冷静。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l75','fall behind','',NULL,'/fɔːl bɪˈhaɪnd/','At first we fell behind.','起初我们落后了。','Don''t fall behind the rest of the class.','别落在全班后面。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l75','as fast as one can','',NULL,'/æz fæst æz wʌn kæn/','I raced as fast as I could.','我尽可能快地跑。','Run as fast as you can to the gate.','尽你所能快跑到大门。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l75','just ahead of','',NULL,'/dʒʌst əˈhed əv/','I crossed the line just ahead of the others.','我刚好领先其他人冲线。','Her car stopped just ahead of ours.','她的车停在我们车的前面一点点。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp1','choice','{"stem":"\"Last Saturday our school ___ its yearly sports day.\"(hold 的过去式)","options":["held","holds","holded","holding"],"answer_index":0,"stem_cn":"上周六我们学校举办了一年一度的运动会。","explanation_cn":"hold 是不规则动词,过去式是 held。✓ Last Saturday our school held its sports day. ✗ holded:不规则动词不加 -ed;✗ holds:一般现在;✗ holding:现在分词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp1','choice','{"stem":"\"When the whistle blew, the runners ___ forward.\"(shoot 的过去式,猛冲)","options":["shooting","shooted","shoot","shot"],"answer_index":3,"stem_cn":"哨声一响,选手们猛冲向前。","explanation_cn":"shoot 是不规则动词,过去式是 shot(此处“猛冲”)。✓ the runners shot forward. ✗ shooted:不规则动词不加 -ed;✗ shoot:原形;✗ shooting:现在分词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp1','choice','{"stem":"\"We ___ by half a second!\"(win 的过去式)","options":["won","winned","win","winning"],"answer_index":0,"stem_cn":"我们以半秒之差赢了!","explanation_cn":"win 是不规则动词,过去式是 won。✓ We won by half a second. ✗ winned:不规则动词不加 -ed;✗ win:原形;✗ winning:现在分词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp2','choice','{"stem":"\"My class ___ the relay race.\"(enter 的过去式,报名参加)","options":["entering","enters","enter","entered"],"answer_index":3,"stem_cn":"我们班报名参加了接力赛。","explanation_cn":"enter 是规则动词,过去式加 -ed = entered。✓ My class entered the relay race. ✗ enter:原形;✗ entering:现在分词;✗ enters:一般现在。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp2','choice','{"stem":"\"Our third runner ___ two others.\"(pass 的过去式,超过)","options":["passing","passes","passed","past"],"answer_index":2,"stem_cn":"我们的第三棒超过了另外两人。","explanation_cn":"pass 是规则动词,过去式 passed(超过)。✓ Our third runner passed two others. ✗ past:是介词/形容词,不是动词过去式;✗ passing:现在分词;✗ passes:一般现在。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp2','choice','{"stem":"\"The crowd ___ as I crossed the line.\"(shout 的过去式)","options":["shouted","shouts","shout","shouting"],"answer_index":0,"stem_cn":"我冲过终点线时,人群欢呼起来。","explanation_cn":"shout 是规则动词,过去式 shouted。✓ The crowd shouted. ✗ shout:原形;✗ shouting:现在分词;✗ shouts:一般现在。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp3','choice','{"stem":"\"I ___ a deep breath and raced as fast as I could.\"(take 的过去式)","options":["taken","taking","take","took"],"answer_index":3,"stem_cn":"我深吸一口气,拼尽全力地跑。","explanation_cn":"take 是不规则动词,过去式是 took。✓ I took a deep breath. ✗ take:原形;✗ taken:过去分词;✗ taking:现在分词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp3','choice','{"stem":"\"At first we ___ behind.\"(fall 的过去式,落后)","options":["fell","fallen","fall","falling"],"answer_index":0,"stem_cn":"起初我们落后了。","explanation_cn":"fall 是不规则动词,过去式是 fell(此处“落后”)。✓ At first we fell behind. ✗ fall:原形;✗ fallen:过去分词;✗ falling:现在分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp3','choice','{"stem":"\"Hundreds of families ___ to watch.\"(come 的过去式)","options":["comes","coming","came","come"],"answer_index":2,"stem_cn":"几百个家庭前来观看。","explanation_cn":"come 是不规则动词,过去式是 came。✓ Hundreds of families came to watch. ✗ come:原形;✗ comes:一般现在;✗ coming:现在分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp4','choice','{"stem":"\"The race ___ place last Saturday.\"(take place 与 last Saturday 搭配的形式)","options":["will take","took","takes","is taking"],"answer_index":1,"stem_cn":"比赛于上周六举行。","explanation_cn":"与过去时间 last Saturday 搭配,用一般过去 took(take place=举行)。✓ The race took place last Saturday. ✗ takes:一般现在;✗ will take:将来;✗ is taking:进行。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp4','choice','{"stem":"\"The team won the city final two weeks ___.\"(“两周前”用哪个词)","options":["since","later","before","ago"],"answer_index":3,"stem_cn":"这支队伍两周前赢了市决赛。","explanation_cn":"“(一段时间)以前”用“时段 + ago”。✓ two weeks ago 两周前。✗ later:是“…之后”;✗ since:接时间点;✗ before:不这样直接接时段表“…前”。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp4','choice','{"stem":"\"Yesterday I ___ in the relay for the first time.\"(与 yesterday 搭配:run 的过去式)","options":["ran","run","am running","will run"],"answer_index":0,"stem_cn":"昨天我第一次参加接力赛。","explanation_cn":"与 yesterday 搭配用一般过去;run 的过去式是 ran。✓ Yesterday I ran in the relay. ✗ run:原形;✗ will run:将来;✗ am running:现在进行。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp5','choice','{"stem":"\"I ___ expect to win at all.\"(一般过去的否定:根本没料到)","options":["haven''t","didn''t","don''t","wasn''t"],"answer_index":1,"stem_cn":"我根本没料到能赢。","explanation_cn":"一般过去的否定用 didn''t + 动词原形。✓ I didn''t expect to win. ✗ don''t:一般现在;✗ wasn''t:后面不接动词原形;✗ haven''t:现在完成。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp5','choice','{"stem":"\"___ your class win the relay race?\"(一般过去的一般疑问)","options":["Was","Do","Has","Did"],"answer_index":3,"stem_cn":"你们班赢了接力赛吗?","explanation_cn":"一般过去的一般疑问用 Did 开头,后面的动词一律用原形。✓ Did your class win the relay race? ✗ Was:后面不接动词原形 win;✗ Do:一般现在;✗ Has:现在完成。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp5','choice','{"stem":"\"The other team ___ finish in time.\"(一般过去的否定:没能及时完成)","options":["hasn''t","doesn''t","didn''t","wasn''t"],"answer_index":2,"stem_cn":"另一队没能及时跑完。","explanation_cn":"一般过去的否定用 didn''t + 原形。✓ The other team didn''t finish in time. ✗ wasn''t:后面不接原形 finish;✗ hasn''t:现在完成;✗ doesn''t:一般现在。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp6','choice','{"stem":"\"In a relay race, each runner passes a ___ to the next.\"(接力棒用哪个词)","options":["whistle","rope","medal","baton"],"answer_index":3,"stem_cn":"在接力赛中,每名选手把接力棒传给下一个人。","explanation_cn":"接力赛里传递的“接力棒”是 baton。✓ each runner passes a baton to the next. ✗ whistle:是“哨子”;✗ medal:是“奖牌”;✗ rope:是“绳子”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp6','choice','{"stem":"\"When the ___ blew, the race began.\"(哨子用哪个词)","options":["whistle","bell","horn","drum"],"answer_index":0,"stem_cn":"哨声一响,比赛就开始了。","explanation_cn":"“哨子”是 whistle。✓ When the whistle blew, the race began. ✗ drum:是“鼓”;✗ bell:是“铃”;✗ horn:是“号角”。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',5,'am2_l75_gp6','choice','{"stem":"\"I crossed the line just ___ of the others.\"(在…前面、领先用哪个词)","options":["behind","beside","below","ahead"],"answer_index":3,"stem_cn":"我刚好领先其他人冲过了终点线。","explanation_cn":"“在…前面、领先”用 ahead (of)。✓ I crossed the line just ahead of the others. ✗ behind:是“在后面”;✗ beside:是“在旁边”;✗ below:是“在下面”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',6,NULL,'choice','{"stem":"美语里\"足球\"常说:","options":["foot-game","football","soccer","kick-ball"],"answer_index":2,"explanation_cn":"美语“足球”说 soccer;英式说 football。✓ We played soccer after school. 放学后我们踢足球。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',6,NULL,'choice','{"stem":"美语里\"运动鞋\"常说:","options":["sneakers","sport-boots","run-shoes","trainers"],"answer_index":0,"explanation_cn":"美语“运动鞋”说 sneakers;英式说 trainers。✓ She wore new sneakers to the race. 她穿着新运动鞋来比赛。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',6,NULL,'choice','{"stem":"relay 的意思是:","options":["游泳","接力赛","跳高","马拉松"],"answer_index":1,"explanation_cn":"relay = 接力赛。✓ the relay race 接力赛。\n顺带记:马拉松 = marathon;跳高 = high jump;游泳 = swimming."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',6,NULL,'choice','{"stem":"whistle 的意思是:","options":["旗帜","奖杯","号角","哨子"],"answer_index":3,"explanation_cn":"whistle = 哨子。✓ When the whistle blew 哨声一响。\n顺带记:奖杯 = trophy;旗帜 = flag;号角 = horn."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',6,NULL,'choice','{"stem":"crowd 的意思是:","options":["人群","冠军","裁判","教练"],"answer_index":0,"explanation_cn":"crowd = 人群。✓ The crowd shouted 人群欢呼起来。\n顺带记:裁判 = referee;教练 = coach;冠军 = champion."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',6,NULL,'choice','{"stem":"expect 的意思是:","options":["忘记","放弃","预料,期待","害怕"],"answer_index":2,"explanation_cn":"expect = 预料、期待。✓ I didn''t expect it 我没料到。\n顺带记:放弃 = give up;忘记 = forget;害怕 = fear."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',7,NULL,'cloze','{"stem":"第 1 空","context":"Last Saturday our school ___1___ its sports day. My class ___2___ the relay race, and I ran the last leg. When the whistle blew, the runners ___3___ forward. We ___4___ by half a second!","blank_no":1,"options":["held","holds","holded","holding"],"answer_index":0,"explanation_cn":"hold 的过去式是 held。✓ our school held its sports day.\n✗ holds:一般现在;✗ holded:不规则动词不加 -ed;✗ holding:现在分词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',7,NULL,'cloze','{"stem":"第 2 空","context":"Last Saturday our school ___1___ its sports day. My class ___2___ the relay race, and I ran the last leg. When the whistle blew, the runners ___3___ forward. We ___4___ by half a second!","blank_no":2,"options":["entered","enter","enters","entering"],"answer_index":0,"explanation_cn":"enter 的过去式是 entered。✓ My class entered the relay race.\n✗ enter:原形;✗ enters:一般现在;✗ entering:现在分词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',7,NULL,'cloze','{"stem":"第 3 空","context":"Last Saturday our school ___1___ its sports day. My class ___2___ the relay race, and I ran the last leg. When the whistle blew, the runners ___3___ forward. We ___4___ by half a second!","blank_no":3,"options":["shot","shoot","shooted","shooting"],"answer_index":0,"explanation_cn":"shoot 的过去式是 shot。✓ the runners shot forward.\n✗ shoot:原形;✗ shooted:不规则动词不加 -ed;✗ shooting:现在分词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',7,NULL,'cloze','{"stem":"第 4 空","context":"Last Saturday our school ___1___ its sports day. My class ___2___ the relay race, and I ran the last leg. When the whistle blew, the runners ___3___ forward. We ___4___ by half a second!","blank_no":4,"options":["won","win","winned","winning"],"answer_index":0,"explanation_cn":"win 的过去式是 won。✓ We won by half a second.\n✗ win:原形;✗ winned:不规则动词不加 -ed;✗ winning:现在分词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',8,NULL,'choice','{"stem":"When did the school hold its sports day?","options":["Next Saturday","Two years ago","Yesterday morning","Last Saturday"],"answer_index":3,"explanation_cn":"课文说 Last Saturday our school held its yearly sports day。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',8,NULL,'choice','{"stem":"Which race did the writer''s class enter?","options":["The relay race — the writer ran the last leg","The long-distance run","The swimming race","The high jump"],"answer_index":0,"explanation_cn":"课文说 My class entered the relay race, and I ran the last leg。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',8,NULL,'choice','{"stem":"How did the race end?","options":["The race was canceled","The writer''s class won by half a second","The writer''s class came in last","It ended in a tie"],"answer_index":1,"explanation_cn":"课文说 We won by half a second。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',9,NULL,'choice','{"stem":"你想说\"上周六我们学校举办了运动会\"(一般过去时,hold 的过去式):","options":["Last Saturday our school holds its sports day.","Last Saturday our school holded its sports day.","Last Saturday our school held its sports day.","Last Saturday our school will hold its sports day."],"answer_index":2,"explanation_cn":"讲过去发生并结束的事用一般过去;hold 的过去式是 held。✓ Last Saturday our school held its sports day. 场合:讲述过去某天做过的事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',9,NULL,'choice','{"stem":"你想说\"你们班赢了接力赛吗?\"(一般过去的一般疑问,用 Did):","options":["Did your class win the relay race?","Was your class win the relay race?","Did your class won the relay race?","Does your class win the relay race?"],"answer_index":0,"explanation_cn":"一般过去的一般疑问用 Did 开头,后面的动词一律用原形。✓ Did your class win the relay race? 场合:问“过去某事发生了没有”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',9,NULL,'choice','{"stem":"你想说\"我根本没料到能赢\"(一般过去的否定,用 didn''t):","options":["I don''t expect to win at all.","I didn''t expect to win at all.","I didn''t expected to win at all.","I wasn''t expect to win at all."],"answer_index":1,"explanation_cn":"一般过去的否定用 didn''t + 动词原形。✓ I didn''t expect to win at all. 场合:说“过去没做/没料到某事”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',10,NULL,'choice','{"stem":"relay 的意思是:","options":["马拉松","跳高","接力赛","游泳"],"answer_index":2,"explanation_cn":"relay = 接力赛。✓ the relay race 接力赛。\n顺带记:马拉松 = marathon;跳高 = high jump;游泳 = swimming."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',10,NULL,'choice','{"stem":"expect 的意思是:","options":["害怕","忘记","放弃","预料,期待"],"answer_index":3,"explanation_cn":"expect = 预料、期待。✓ I didn''t expect it 我没料到。\n顺带记:放弃 = give up;忘记 = forget;害怕 = fear."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',10,NULL,'choice','{"stem":"\"Last Saturday our school ___ its sports day.\"(hold 的过去式)","options":["held","holding","holded","holds"],"answer_index":0,"stem_cn":"上周六我们学校举办了运动会。","explanation_cn":"hold 的过去式是 held。✓ our school held its sports day.\n✗ holds:一般现在;✗ holded:不规则动词不加 -ed;✗ holding:现在分词。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',10,NULL,'choice','{"stem":"\"___ your class win the relay race?\"(一般过去的一般疑问)","options":["Do","Has","Did","Was"],"answer_index":2,"stem_cn":"你们班赢了接力赛吗?","explanation_cn":"一般过去的一般疑问用 Did 开头,后面的动词一律用原形。✓ Did your class win the relay race?\n✗ Was:后不接原形 win;✗ Do:一般现在;✗ Has:现在完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',10,NULL,'choice','{"stem":"\"take a deep breath\" 的意思是:","options":["停下休息","深吸一口气","大声喊叫","转身离开"],"answer_index":1,"explanation_cn":"take a deep breath = 深吸一口气(常在紧张或用力前)。如 I took a deep breath and raced。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',10,NULL,'choice','{"stem":"\"fall behind\" 的意思是:","options":["加速","摔倒","领先","落后"],"answer_index":3,"explanation_cn":"fall behind = 落后、跟不上。如 At first we fell behind 起初我们落后了。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',10,NULL,'choice','{"stem":"Why did the writer think they had no chance at first?","options":["Because at first their team fell behind","Because they arrived late","Because a runner got hurt","Because it started to rain"],"answer_index":0,"passage":"Last Saturday our school held its yearly sports day. The sun shone, and hundreds of families came to watch. My class entered the relay race, and I ran the last leg. When the whistle blew, the runners shot forward. At first we fell behind, and I thought we had no chance. But our third runner passed two others and handed me the baton. I took a deep breath and raced as fast as I could. The crowd shouted, and I crossed the line just ahead of the others. We won by half a second! I didn''t expect it at all. It was the best sports day our class ever had.","explanation_cn":"课文说 At first we fell behind, and I thought we had no chance。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',10,NULL,'choice','{"stem":"How did the writer''s class win the race?","options":["The other teams gave up","The writer started before the whistle","The third runner passed two others and handed over the baton, and the writer raced ahead to cross first","They only had two runners"],"answer_index":2,"passage":"Last Saturday our school held its yearly sports day. The sun shone, and hundreds of families came to watch. My class entered the relay race, and I ran the last leg. When the whistle blew, the runners shot forward. At first we fell behind, and I thought we had no chance. But our third runner passed two others and handed me the baton. I took a deep breath and raced as fast as I could. The crowd shouted, and I crossed the line just ahead of the others. We won by half a second! I didn''t expect it at all. It was the best sports day our class ever had.","explanation_cn":"课文说 our third runner passed two others and handed me the baton. I… raced… and crossed the line just ahead of the others。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',10,NULL,'choice','{"stem":"By how much did the class win?","options":["By half a second","By one meter","By a full minute","By ten seconds"],"answer_index":0,"audio":"Last Saturday our school held its yearly sports day. The sun shone, and hundreds of families came to watch. My class entered the relay race, and I ran the last leg. When the whistle blew, the runners shot forward. At first we fell behind, and I thought we had no chance. But our third runner passed two others and handed me the baton. I took a deep breath and raced as fast as I could. The crowd shouted, and I crossed the line just ahead of the others. We won by half a second! I didn''t expect it at all. It was the best sports day our class ever had.","explanation_cn":"课文说 We won by half a second。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l75',10,NULL,'choice','{"stem":"Did the writer expect to win?","options":["Yes — she was sure of it","No — not at all","Yes — she had practiced for years","No comment was made"],"answer_index":1,"audio":"Last Saturday our school held its yearly sports day. The sun shone, and hundreds of families came to watch. My class entered the relay race, and I ran the last leg. When the whistle blew, the runners shot forward. At first we fell behind, and I thought we had no chance. But our third runner passed two others and handed me the baton. I took a deep breath and raced as fast as I could. The crowd shouted, and I crossed the line just ahead of the others. We won by half a second! I didn''t expect it at all. It was the best sports day our class ever had.","explanation_cn":"课文说 I didn''t expect it at all。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l76',2,10,76,'What Have You Been Up To?','你最近在忙什么?','KS4/28/52 现在完成时 vs 现在完成进行时(教材 L76 Key structures,方案B换情节包):现在完成 has/have done(结果、经历,如 have taken/have learned/have found)、现在完成进行 has/have been doing(持续过程,如 have been studying/have been working/have been painting)、两者对比、以及 since(时间点)/ for(时段)','“我好久没见你了!”埃玛说,“你最近在忙什么?”“从一月起我一直在学摄影,”利奥说,“我已经拍了几百张照片了,也学到了好多。”“太好了!我一直在咖啡馆打工,不过一直没多少空闲时间。”“你的画画完了吗?”利奥问。“还没——我已经画了三个星期了,不过快好了。”“那咱俩都挺忙的。”“是啊,但我们终于挤出一个下午见面了!”“我一直很想念这些闲聊,”埃玛笑着说。“我也是。下次别隔这么久了。”','{"q":"Listen and answer — Why haven''t Emma and Leo met for so long?","options":["They have both been very busy","They had an argument","They live in different countries","They forgot each other"],"answer_index":0}'::jsonb,'{"title":"KS4/28/52 现在完成 vs 现在完成进行 + since/for","intro":"两种时态都连着“过去到现在”,但侧重不同:①现在完成 have/has done——强调“结果、已完成、经历”(I have taken hundreds of photos 已经拍了;I have learned a lot 学到了);②现在完成进行 have/has been doing——强调“一直在做、持续的过程”(I have been studying photography 一直在学;I have been painting it 一直在画)。时间词:since + 时间点(since January);for + 一段时间(for three weeks / for ages)。疑问与否定:Have you…? / haven''t done。","table":{"headers":["时态","侧重与例子"],"rows":[["现在完成(结果/经历)","I have taken hundreds of photos already."],["现在完成进行(持续过程)","I have been studying photography since January."],["对比","have learned(学到了) vs have been studying(一直在学)"],["since + 时间点 / for + 时段","since January / for three weeks"],["疑问与否定","Have you finished? / I haven''t had much time."]]},"specialRules":[{"rule":"美语里“公寓”说 apartment(英式 flat)、“假期”说 vacation(英式 holiday)、“电梯”说 elevator(英式 lift);本课已按美语写。","mark":"apartment/vacation"},{"rule":"强调“做出的结果/数量/是否完成”用现在完成(have done);强调“一直在进行、还没停”用现在完成进行(have been doing)。since 接时间点,for 接一段时间。","mark":"done vs been doing"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l76',1,'Emma','"I haven''t seen you for ages!" said Emma. "What have you been doing?"','“我好久没见你了!”埃玛说,“你最近在忙什么?”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l76',2,'Leo','"I have been studying photography since January," said Leo. "I have taken hundreds of photos already, and I have learned so much."','“从一月起我一直在学摄影,”利奥说,“我已经拍了几百张照片了,也学到了好多。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l76',3,'Emma','"That''s great! I have been working at the café, but I haven''t had much free time." "Have you finished your painting?" Leo asked.','“太好了!我一直在咖啡馆打工,不过一直没多少空闲时间。”“你的画画完了吗?”利奥问。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l76',4,'Emma','"Not yet — I have been painting it for three weeks, but it''s almost done." "We have both been busy, then."','“还没——我已经画了三个星期了,不过快好了。”“那咱俩都挺忙的。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l76',5,'Emma','"Yes, but we have finally found an afternoon to meet!" "I have missed these chats," Emma said with a smile. "So have I. Let''s not wait so long next time."','“是啊,但我们终于挤出一个下午见面了!”“我一直很想念这些闲聊,”埃玛笑着说。“我也是。下次别隔这么久了。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
