INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l76','haven''t seen sb for ages','',NULL,'/ˈhævnt siːn fɔːr ˈeɪdʒɪz/','I haven''t seen you for ages!','我好久没见你了!','We haven''t seen each other for ages.','我们好久没见面了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l76','What have you been up to?','',NULL,'/wʌt hæv juː bɪn ʌp tuː/','Hi! What have you been up to?','嗨!你最近在忙些什么?','What have the kids been up to today?','孩子们今天都在忙些什么?') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l76','free time','',NULL,'/friː taɪm/','I haven''t had much free time.','我一直没多少空闲时间。','She reads in her free time.','她在空闲时间读书。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l76','So have I','',NULL,'/soʊ hæv aɪ/','"I''ve missed this." "So have I."','“我一直很想念这个。”“我也是。”','"I''ve finished mine." "So have I."','“我做完我的了。”“我也是。”') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp1','choice','{"stem":"\"I ___ hundreds of photos already.\"(强调已拍到的结果:现在完成)","options":["am taking","had taken","took","have taken"],"answer_index":3,"stem_cn":"我已经拍了几百张照片了。","explanation_cn":"强调“已经拍到的结果、数量”,用现在完成 have + 过去分词。✓ I have taken hundreds of photos already. ✗ took:一般过去,不含“到现在”;✗ am taking:现在进行;✗ had taken:过去完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp1','choice','{"stem":"\"We have finally ___ an afternoon to meet.\"(find 的过去分词:现在完成)","options":["founded","found","find","finding"],"answer_index":1,"stem_cn":"我们终于找到了一个下午能见面。","explanation_cn":"现在完成 have + 过去分词;find 的过去分词是 found。✓ We have finally found an afternoon to meet. ✗ find:原形;✗ founded:那是 found(创立)的过去式,词义不同;✗ finding:现在分词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp1','choice','{"stem":"\"I ___ so much this year.\"(强调学到的结果:现在完成)","options":["had learned","am learning","learned","have learned"],"answer_index":3,"stem_cn":"我今年学到了很多。","explanation_cn":"强调“学到的结果”,用现在完成。✓ I have learned so much this year. ✗ learned:一般过去;✗ am learning:现在进行;✗ had learned:过去完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp2','choice','{"stem":"\"I ___ photography since January.\"(一直在学、强调过程:现在完成进行)","options":["had studied","studied","have been studying","study"],"answer_index":2,"stem_cn":"从一月起我一直在学摄影。","explanation_cn":"强调“从一月一直学到现在的过程”,用现在完成进行 have been + 现在分词。✓ I have been studying photography since January. ✗ studied:一般过去;✗ study:一般现在;✗ had studied:过去完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp2','choice','{"stem":"\"I ___ at the café lately.\"(一直在打工:现在完成进行)","options":["had worked","have been working","work","worked"],"answer_index":1,"stem_cn":"最近我一直在咖啡馆打工。","explanation_cn":"强调“最近一直在打工的过程”,用现在完成进行。✓ I have been working at the café lately. ✗ worked:一般过去;✗ work:一般现在;✗ had worked:过去完成。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp2','choice','{"stem":"\"I ___ this painting for three weeks.\"(一直在画:现在完成进行)","options":["had painted","painted","have been painting","paint"],"answer_index":2,"stem_cn":"这幅画我已经画了三个星期了。","explanation_cn":"强调“三个星期一直在画的过程”,用现在完成进行。✓ I have been painting this painting for three weeks. ✗ painted:一般过去;✗ paint:一般现在;✗ had painted:过去完成。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp3','choice','{"stem":"\"''I ___ hundreds of photos,'' she said, showing the finished album.\"(强调结果与数量:现在完成)","options":["have taken","take","took","have been taking"],"answer_index":0,"stem_cn":"“我拍了几百张照片,”她说着,拿出了做好的相册。","explanation_cn":"说话人拿出“做好的相册”，强调结果与数量,用现在完成。✓ I have taken hundreds of photos. ✗ have been taking:强调过程,不配“做好的相册”这个结果;✗ took:一般过去;✗ take:一般现在。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp3','choice','{"stem":"\"''I ___ photography, and I still go to class every week.''\"(强调一直在学、还没停:现在完成进行)","options":["study","have been studying","have studied","studied"],"answer_index":1,"stem_cn":"“我一直在学摄影,现在每周还去上课。”","explanation_cn":"“现在每周还去上课”说明动作还在持续,强调过程,用现在完成进行。✓ I have been studying photography, and I still go to class. ✗ have studied:强调结果,不配“还在上课”;✗ studied:一般过去;✗ study:一般现在。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp3','choice','{"stem":"\"''We ___ busy all month,'' they agreed.\"(一直处于忙碌状态:现在完成)","options":["had been","are being","were","have been"],"answer_index":3,"stem_cn":"“我们这一整月一直都很忙,”他们都这么说。","explanation_cn":"“一整月一直处于忙碌状态”,用现在完成 have been(be 的现在完成)。✓ We have been busy all month. ✗ are being:现在进行,不含“一整月到现在”;✗ were:一般过去;✗ had been:过去完成。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp4','choice','{"stem":"\"I''ve been studying photography ___ January.\"(接时间点用哪个词)","options":["from","for","since","ago"],"answer_index":2,"stem_cn":"从一月起我一直在学摄影。","explanation_cn":"接“时间点(January)”用 since。✓ I''ve been studying photography since January. ✗ for:接一段时间;✗ ago:用在句末;✗ from:此处固定用 since。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp4','choice','{"stem":"\"I haven''t seen you ___ ages!\"(接一段时间用哪个词)","options":["in","since","ago","for"],"answer_index":3,"stem_cn":"我好久没见你了!","explanation_cn":"接“一段时间(ages)”用 for。✓ I haven''t seen you for ages! ✗ since:接时间点;✗ ago:用在句末;✗ in:此处不合。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp4','choice','{"stem":"\"I''ve been painting it ___ three weeks.\"(接一段时间用哪个词)","options":["since","by","for","ago"],"answer_index":2,"stem_cn":"这幅画我画了三个星期了。","explanation_cn":"接“一段时间(three weeks)”用 for。✓ I''ve been painting it for three weeks. ✗ since:接时间点;✗ ago:用在句末;✗ by:表“到…之前”，此处不合。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp5','choice','{"stem":"\"___ you finished your painting yet?\"(现在完成的一般疑问)","options":["Do","Are","Did","Have"],"answer_index":3,"stem_cn":"你的画画完了吗?","explanation_cn":"现在完成的一般疑问用 Have 开头,后面用过去分词。✓ Have you finished your painting yet? ✗ Did:那是一般过去;✗ Are:后面不接过去分词 finished 构成完成;✗ Do:一般现在。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp5','choice','{"stem":"\"I ___ much free time lately.\"(现在完成的否定:一直没多少空)","options":["didn''t have","haven''t had","don''t have","hadn''t had"],"answer_index":1,"stem_cn":"最近我一直没多少空闲时间。","explanation_cn":"“最近一直没有多少空”,用现在完成的否定 haven''t + 过去分词。✓ I haven''t had much free time lately. ✗ didn''t have:一般过去;✗ don''t have:一般现在;✗ hadn''t had:过去完成。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp5','choice','{"stem":"\"I ___ you for ages!\"(现在完成的否定:好久没见)","options":["didn''t see","don''t see","haven''t seen","hadn''t seen"],"answer_index":2,"stem_cn":"我好久没见到你了!","explanation_cn":"“好久没见到、延续到现在”,用现在完成的否定。✓ I haven''t seen you for ages! ✗ didn''t see:一般过去;✗ don''t see:一般现在;✗ hadn''t seen:过去完成。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp6','choice','{"stem":"\"Leo has been learning ___ — taking pictures with a camera.\"(摄影用哪个词)","options":["singing","painting","cooking","photography"],"answer_index":3,"stem_cn":"利奥一直在学摄影——用相机拍照。","explanation_cn":"“用相机拍照”这门爱好/学问是 photography(摄影)。✓ Leo has been learning photography. ✗ painting:是“绘画”;✗ cooking:是“烹饪”;✗ singing:是“唱歌”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp6','choice','{"stem":"\"''I''ve missed these ___,'' Emma said.\"(闲聊、聊天用哪个词)","options":["chats","exams","races","meals"],"answer_index":0,"stem_cn":"“我很想念这些闲聊,”埃玛说。","explanation_cn":"朋友间的“闲聊、聊天”是 chat(复数 chats)。✓ I''ve missed these chats. ✗ races:是“比赛”;✗ exams:是“考试”;✗ meals:是“饭菜”。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',5,'am2_l76_gp6','choice','{"stem":"\"They''ve both been very ___ this month.\"(忙碌用哪个词)","options":["angry","busy","lazy","sleepy"],"answer_index":1,"stem_cn":"他们俩这个月都很忙。","explanation_cn":"“忙碌的”用 busy。✓ They''ve both been very busy this month. ✗ lazy:是“懒的”;✗ sleepy:是“困的”;✗ angry:是“生气的”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',6,NULL,'choice','{"stem":"美语里\"公寓\"常说:","options":["stay-house","flat","live-room","apartment"],"answer_index":3,"explanation_cn":"美语“公寓”说 apartment;英式说 flat。✓ She lives in a small apartment downtown. 她住在市中心一间小公寓里。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',6,NULL,'choice','{"stem":"美语里\"假期\"常说:","options":["holiday","vacation","rest-day","off-time"],"answer_index":1,"explanation_cn":"美语“假期”说 vacation;英式说 holiday。✓ We took a lot of photos on vacation. 假期里我们拍了很多照片。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',6,NULL,'choice','{"stem":"photography 的意思是:","options":["绘画","写作","唱歌","摄影"],"answer_index":3,"explanation_cn":"photography = 摄影。✓ studying photography 学摄影。\n顺带记:绘画 = painting;写作 = writing;唱歌 = singing."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',6,NULL,'choice','{"stem":"busy 的意思是:","options":["忙碌的","无聊的","空闲的","疲惫的"],"answer_index":0,"explanation_cn":"busy = 忙碌的。✓ We have both been busy 我们俩都很忙。\n顺带记:空闲的 = free;疲惫的 = tired;无聊的 = bored."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',6,NULL,'choice','{"stem":"miss 的意思是:","options":["忘记","想念","遇见","讨厌"],"answer_index":1,"explanation_cn":"miss = 想念。✓ I have missed these chats 我一直很想念这些闲聊。\n顺带记:遇见 = meet;忘记 = forget;讨厌 = hate."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',6,NULL,'choice','{"stem":"finally 的意思是:","options":["起初","突然","终于,最后","从不"],"answer_index":2,"explanation_cn":"finally = 终于、最后。✓ we have finally found an afternoon 我们终于挤出一个下午。\n顺带记:起初 = at first;突然 = suddenly;从不 = never."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',7,NULL,'cloze','{"stem":"第 1 空","context":"\"I ___1___ you for ages!\" said Emma. \"I ___2___ photography since January,\" said Leo. \"I ___3___ hundreds of photos already.\" \"I''ve been working at the café, but I ___4___ much free time.\"","blank_no":1,"options":["haven''t seen","didn''t see","don''t see","hadn''t seen"],"answer_index":0,"explanation_cn":"“好久没见、延续到现在”用现在完成的否定。✓ I haven''t seen you for ages!\n✗ didn''t see:一般过去;✗ don''t see:一般现在;✗ hadn''t seen:过去完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',7,NULL,'cloze','{"stem":"第 2 空","context":"\"I ___1___ you for ages!\" said Emma. \"I ___2___ photography since January,\" said Leo. \"I ___3___ hundreds of photos already.\" \"I''ve been working at the café, but I ___4___ much free time.\"","blank_no":2,"options":["have been studying","studied","study","had studied"],"answer_index":0,"explanation_cn":"强调从一月一直学到现在的过程,用现在完成进行。✓ I have been studying photography since January.\n✗ studied:一般过去;✗ study:一般现在;✗ had studied:过去完成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',7,NULL,'cloze','{"stem":"第 3 空","context":"\"I ___1___ you for ages!\" said Emma. \"I ___2___ photography since January,\" said Leo. \"I ___3___ hundreds of photos already.\" \"I''ve been working at the café, but I ___4___ much free time.\"","blank_no":3,"options":["have taken","took","am taking","had taken"],"answer_index":0,"explanation_cn":"强调已拍到的结果与数量,用现在完成。✓ I have taken hundreds of photos already.\n✗ took:一般过去;✗ am taking:现在进行;✗ had taken:过去完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',7,NULL,'cloze','{"stem":"第 4 空","context":"\"I ___1___ you for ages!\" said Emma. \"I ___2___ photography since January,\" said Leo. \"I ___3___ hundreds of photos already.\" \"I''ve been working at the café, but I ___4___ much free time.\"","blank_no":4,"options":["haven''t had","didn''t have","don''t have","hadn''t had"],"answer_index":0,"explanation_cn":"“最近一直没多少空”用现在完成的否定。✓ I haven''t had much free time.\n✗ didn''t have:一般过去;✗ don''t have:一般现在;✗ hadn''t had:过去完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',8,NULL,'choice','{"stem":"What has Leo been studying since January?","options":["Music","Photography","Cooking","Painting"],"answer_index":1,"explanation_cn":"课文说 I have been studying photography since January(Leo 的话)。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',8,NULL,'choice','{"stem":"What has Emma been doing?","options":["Studying photography too","Traveling abroad","Resting at home","Working at the café, with little free time"],"answer_index":3,"explanation_cn":"课文说 I have been working at the café, but I haven''t had much free time(Emma 的话)。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',8,NULL,'choice','{"stem":"Has Emma finished her painting?","options":["Yes, she finished it this morning","No, she never started it","Not yet, but it''s almost done","Yes, she finished it months ago"],"answer_index":2,"explanation_cn":"课文说 Not yet — I have been painting it for three weeks, but it''s almost done。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',9,NULL,'choice','{"stem":"你想说\"从一月起我一直在学摄影\"(现在完成进行,强调持续 + since 时间点):","options":["I have been studying photography for January.","I have been studying photography since January.","I studied photography since January.","I am studying photography since January."],"answer_index":1,"explanation_cn":"强调“一直学到现在的过程”用现在完成进行,时间点用 since。✓ I have been studying photography since January. 场合:说“从某时起一直在做某事、还在做”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',9,NULL,'choice','{"stem":"你想说\"我已经拍了几百张照片了\"(现在完成,强调结果):","options":["I have taken hundreds of photos already.","I have been taking hundreds of photos already.","I take hundreds of photos already.","I took hundreds of photos already."],"answer_index":0,"explanation_cn":"强调“已经做出的结果、数量”用现在完成 have + 过去分词。✓ I have taken hundreds of photos already. 场合:说“到现在已经完成/积累了多少”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',9,NULL,'choice','{"stem":"你想说\"我好久没见你了!\"(现在完成的否定 + for ages):","options":["I haven''t seen you since ages!","I didn''t see you for ages!","I haven''t seen you for ages!","I don''t see you for ages!"],"answer_index":2,"explanation_cn":"“好久没见、延续到现在”用现在完成的否定,for 接一段时间。✓ I haven''t seen you for ages! 场合:久别重逢时的招呼。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',10,NULL,'choice','{"stem":"photography 的意思是:","options":["摄影","写作","绘画","唱歌"],"answer_index":0,"explanation_cn":"photography = 摄影。✓ studying photography 学摄影。\n顺带记:绘画 = painting;写作 = writing;唱歌 = singing."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',10,NULL,'choice','{"stem":"miss 的意思是:","options":["讨厌","想念","忘记","遇见"],"answer_index":1,"explanation_cn":"miss = 想念。✓ I have missed these chats 我一直很想念这些闲聊。\n顺带记:遇见 = meet;忘记 = forget;讨厌 = hate."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',10,NULL,'choice','{"stem":"\"I ___ photography since January.\"(一直在学、强调过程:现在完成进行)","options":["studied","had studied","have been studying","study"],"answer_index":2,"stem_cn":"从一月起我一直在学摄影。","explanation_cn":"强调“一直学到现在的过程”用现在完成进行。✓ I have been studying photography since January.\n✗ studied:一般过去;✗ study:一般现在;✗ had studied:过去完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',10,NULL,'choice','{"stem":"\"I ___ hundreds of photos already.\"(强调结果:现在完成)","options":["have taken","took","am taking","had taken"],"answer_index":0,"stem_cn":"我已经拍了几百张照片了。","explanation_cn":"强调“已拍到的结果”用现在完成。✓ I have taken hundreds of photos already.\n✗ took:一般过去;✗ am taking:现在进行;✗ had taken:过去完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',10,NULL,'choice','{"stem":"\"What have you been up to?\" 的意思是:","options":["你几点起床?","你叫什么名字?","你最近一直在忙些什么?","你要去哪里?"],"answer_index":2,"explanation_cn":"What have you been up to? = 你最近(一直)在忙些什么?——久别重逢时问近况的常用语。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',10,NULL,'choice','{"stem":"\"I''ve been painting it ___ three weeks.\" 空里应填:","options":["at","since","ago","for"],"answer_index":3,"explanation_cn":"接“一段时间(three weeks)”用 for。✓ I''ve been painting it for three weeks。since 才接时间点。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',10,NULL,'choice','{"stem":"Why haven''t Emma and Leo met for a long time?","options":["They have both been very busy","They had a quarrel","They lost each other''s numbers","They live far apart"],"answer_index":0,"passage":"\"I haven''t seen you for ages!\" said Emma. \"What have you been doing?\" \"I have been studying photography since January,\" said Leo. \"I have taken hundreds of photos already, and I have learned so much.\" \"That''s great! I have been working at the café, but I haven''t had much free time.\" \"Have you finished your painting?\" Leo asked. \"Not yet — I have been painting it for three weeks, but it''s almost done.\" \"We have both been busy, then.\" \"Yes, but we have finally found an afternoon to meet!\" \"I have missed these chats,\" Emma said with a smile. \"So have I. Let''s not wait so long next time.\"","explanation_cn":"课文说 We have both been busy, then. / but we have finally found an afternoon to meet。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',10,NULL,'choice','{"stem":"What have Emma and Leo each been doing recently?","options":["Both have been resting","Both have been on vacation","Leo has been studying photography; Emma has been working at the café","Leo has been painting; Emma has been studying"],"answer_index":2,"passage":"\"I haven''t seen you for ages!\" said Emma. \"What have you been doing?\" \"I have been studying photography since January,\" said Leo. \"I have taken hundreds of photos already, and I have learned so much.\" \"That''s great! I have been working at the café, but I haven''t had much free time.\" \"Have you finished your painting?\" Leo asked. \"Not yet — I have been painting it for three weeks, but it''s almost done.\" \"We have both been busy, then.\" \"Yes, but we have finally found an afternoon to meet!\" \"I have missed these chats,\" Emma said with a smile. \"So have I. Let''s not wait so long next time.\"","explanation_cn":"课文说 Leo:I have been studying photography;Emma:I have been working at the café。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',10,NULL,'choice','{"stem":"How long has Leo been studying photography?","options":["For three weeks","Since last year","For ages","Since January"],"answer_index":3,"audio":"\"I haven''t seen you for ages!\" said Emma. \"What have you been doing?\" \"I have been studying photography since January,\" said Leo. \"I have taken hundreds of photos already, and I have learned so much.\" \"That''s great! I have been working at the café, but I haven''t had much free time.\" \"Have you finished your painting?\" Leo asked. \"Not yet — I have been painting it for three weeks, but it''s almost done.\" \"We have both been busy, then.\" \"Yes, but we have finally found an afternoon to meet!\" \"I have missed these chats,\" Emma said with a smile. \"So have I. Let''s not wait so long next time.\"","explanation_cn":"课文说 I have been studying photography since January。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l76',10,NULL,'choice','{"stem":"How does Emma feel about their chats?","options":["She finds them boring","She dislikes them","She has missed them","She has no time for them"],"answer_index":2,"audio":"\"I haven''t seen you for ages!\" said Emma. \"What have you been doing?\" \"I have been studying photography since January,\" said Leo. \"I have taken hundreds of photos already, and I have learned so much.\" \"That''s great! I have been working at the café, but I haven''t had much free time.\" \"Have you finished your painting?\" Leo asked. \"Not yet — I have been painting it for three weeks, but it''s almost done.\" \"We have both been busy, then.\" \"Yes, but we have finally found an afternoon to meet!\" \"I have missed these chats,\" Emma said with a smile. \"So have I. Let''s not wait so long next time.\"","explanation_cn":"课文说 I have missed these chats, Emma said with a smile。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l77',2,10,77,'The Oldest Bridge in Town','镇上最老的桥','KS5/29/53 一般过去时 / 现在完成时 / 现在完成进行时 三时态对比(教材 L77 Key structures,方案B换情节包):过去某时完成用一般过去(was built/appeared/discovered)、影响持续到现在用现在完成(has stood/have crossed/has remained/has been repaired)、持续动作强调过程用现在完成进行(have been examining/have been working);辅以时间状语 for(时段)/ since(时间点)/ ago(时段+ago)','专家们已经对镇上最老的桥考察了六个月。这座桥建于1850年,170多年前。从那时起它就横跨在河上,成千上万的人从上面走过。最近,古老的石头上出现了裂缝,于是市里决定仔细研究它。专家们发现,最初的桥有一部分是木制的。“我们从去年春天起一直在研究它,”一位专家说,“我们已经了解了很多关于它当初是怎么建造的。”木制部分很久以前就被换成了石头,但设计几个世纪以来一直没变。这座桥修过很多次,但它看起来几乎和1850年时一样。如今它仍是镇上最古老的建筑之一——好几代人都喜爱它。','{"q":"Listen and answer — How long have experts been examining the bridge?","options":["For six months","For six years","For six weeks","For sixty years"],"answer_index":0}'::jsonb,'{"title":"KS5/29/53 一般过去 / 现在完成 / 现在完成进行 + for/since/ago","intro":"本课对比三种时态:①一般过去时——过去某个时间点完成的事(The bridge was built in 1850);②现在完成时——过去发生、影响或状态延续到现在(It has stood here since 1850);③现在完成进行时——从过去一直做到现在、强调过程(Experts have been examining it for six months)。时间词:for + 一段时间(for six months);since + 时间点(since 1850);一段时间 + ago(170 years ago)。","table":{"headers":["时态/时间词","例子"],"rows":[["一般过去(过去某点)","The bridge was built in 1850."],["现在完成(延续到今)","It has stood over the river since 1850."],["现在完成进行(强调过程)","Experts have been examining it for six months."],["for + 时段 / since + 时间点","for centuries / since last spring"],["时段 + ago","It was built 170 years ago."]]},"specialRules":[{"rule":"美语里“人行道”说 sidewalk(英式 pavement)、“市中心”说 downtown(英式 city centre);本课已按美语写。","mark":"sidewalk/downtown"},{"rule":"for 接“一段时间”(for six months);since 接“时间点/起点”(since 1850);“一段时间 + ago”表示“多久以前”(170 years ago)。三者别混。","mark":"for/since/ago"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l77',1,NULL,'Experts have been examining the oldest bridge in our town for six months. The bridge was built in 1850, more than 170 years ago.','专家们已经对镇上最老的桥考察了六个月。这座桥建于1850年,170多年前。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l77',2,NULL,'It has stood over the river since then, and thousands of people have crossed it. Recently, cracks appeared in the old stone, so the city decided to study it carefully.','从那时起它就横跨在河上,成千上万的人从上面走过。最近,古老的石头上出现了裂缝,于是市里决定仔细研究它。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l77',3,NULL,'The experts discovered that the original bridge was partly wooden. "We have been working on this since last spring," one expert said. "We have learned a lot about how it was made."','专家们发现,最初的桥有一部分是木制的。“我们从去年春天起一直在研究它,”一位专家说,“我们已经了解了很多关于它当初是怎么建造的。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l77',4,NULL,'The wooden parts were replaced with stone long ago, but the design has remained the same for centuries.','木制部分很久以前就被换成了石头,但设计几个世纪以来一直没变。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l77',5,NULL,'The bridge has been repaired many times, yet it still looks almost the same as it did in 1850. Today it remains one of the oldest structures in town — and people have loved it for generations.','这座桥修过很多次,但它看起来几乎和1850年时一样。如今它仍是镇上最古老的建筑之一——好几代人都喜爱它。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
