INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l77','fall','autumn','秋天;美语 fall,英式 autumn') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l77','have been doing (for/since)','',NULL,'/hæv bɪn ˈduːɪŋ/','Experts have been examining the bridge for six months.','专家们对这座桥考察了六个月。','She has been studying English since 2020.','她从2020年起一直在学英语。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l77','stand over the river','',NULL,'/stænd ˈoʊvər ðə ˈrɪvər/','The bridge has stood over the river since 1850.','这座桥自1850年起就横跨在河上。','A tall tower stands over the harbor.','一座高塔矗立在港口上方。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l77','be replaced with','',NULL,'/bi rɪˈpleɪst wɪð/','The wooden parts were replaced with stone.','木制部分被换成了石头。','The old pipes were replaced with new ones.','旧管子换成了新的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l77','remain the same','',NULL,'/rɪˈmeɪn ðə seɪm/','The design has remained the same for centuries.','几个世纪以来设计一直没变。','His opinion remained the same after the talk.','谈完之后他的看法依旧没变。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp1','choice','{"stem":"\"The bridge ___ in 1850.\"(过去某年建成:一般过去被动)","options":["is built","was built","was building","has been built"],"answer_index":1,"stem_cn":"这座桥建于1850年。","explanation_cn":"过去某年建成、且是“被建造”,用一般过去的被动 was + 过去分词。✓ The bridge was built in 1850. ✗ has been built:现在完成,不配 in 1850 这种明确过去时间;✗ is built:一般现在;✗ was building:进行,意思成了“正在建”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp1','choice','{"stem":"\"Recently, cracks ___ in the old stone.\"(出现了:一般过去)","options":["appeared","have appeared","appear","were appearing"],"answer_index":0,"stem_cn":"最近,古老的石头上出现了裂缝。","explanation_cn":"过去某时“出现了”,用一般过去时。✓ Recently, cracks appeared in the old stone. ✗ have appeared:现在完成;✗ were appearing:进行;✗ appear:一般现在。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp1','choice','{"stem":"\"The experts ___ that the original bridge was partly wooden.\"(发现:一般过去)","options":["were discovering","have discovered","discover","discovered"],"answer_index":3,"stem_cn":"专家们发现,最初的桥有一部分是木制的。","explanation_cn":"过去“发现了”,用一般过去时。✓ The experts discovered that the bridge was partly wooden. ✗ have discovered:现在完成;✗ were discovering:进行;✗ discover:一般现在。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp2','choice','{"stem":"\"The bridge ___ over the river since 1850.\"(一直矗立、延续至今:现在完成)","options":["stood","has stood","is standing","had stood"],"answer_index":1,"stem_cn":"自1850年以来,这座桥一直横跨在河上。","explanation_cn":"从1850年一直矗立到现在,用现在完成时。✓ The bridge has stood over the river since 1850. ✗ stood:一般过去,不含“延续到现在”;✗ is standing:进行,表此刻;✗ had stood:过去完成,时间点不对。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp2','choice','{"stem":"\"Thousands of people ___ it over the years.\"(走过、经历延续至今:现在完成)","options":["are crossing","had crossed","crossed","have crossed"],"answer_index":3,"stem_cn":"这些年来,成千上万的人从桥上走过。","explanation_cn":"这些年来无数人走过、经历延续至今,用现在完成时。✓ Thousands of people have crossed it. ✗ crossed:一般过去;✗ are crossing:进行;✗ had crossed:过去完成。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp2','choice','{"stem":"\"The design ___ the same for centuries.\"(一直保持不变:现在完成)","options":["is remaining","has remained","remained","had remained"],"answer_index":1,"stem_cn":"几个世纪以来,设计一直没变。","explanation_cn":"设计一直保持不变到现在,用现在完成时。✓ The design has remained the same for centuries. ✗ remained:一般过去;✗ is remaining:进行;✗ had remained:过去完成。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp3','choice','{"stem":"\"Experts ___ the old bridge for six months.\"(一直在考察、强调过程:现在完成进行)","options":["have been examining","have examined","examined","are examining"],"answer_index":0,"stem_cn":"专家们已经对这座老桥考察了六个月。","explanation_cn":"从过去一直考察到现在、强调持续过程,用现在完成进行时。✓ Experts have been examining the bridge for six months. ✗ examined:一般过去;✗ are examining:现在进行,不含“已持续六个月”;✗ have examined:现在完成,不强调过程。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp3','choice','{"stem":"\"''We ___ on this since last spring,'' one expert said.\"(一直在研究:现在完成进行)","options":["have worked","are working","worked","have been working"],"answer_index":3,"stem_cn":"“我们从去年春天起一直在研究它,”一位专家说。","explanation_cn":"从去年春天一直研究到现在,用现在完成进行时。✓ We have been working on this since last spring. ✗ worked:一般过去;✗ are working:现在进行;✗ have worked:现在完成,不强调持续过程。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp3','choice','{"stem":"\"The city ___ ways to protect the bridge lately.\"(最近一直在寻找:现在完成进行)","options":["has looked for","is looking for","has been looking for","looked for"],"answer_index":2,"stem_cn":"最近,市里一直在想办法保护这座桥。","explanation_cn":"最近一直在找、强调持续,用现在完成进行时。✓ The city has been looking for ways to protect the bridge. ✗ looked for:一般过去;✗ is looking for:现在进行;✗ has looked for:现在完成,不强调过程。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp4','choice','{"stem":"\"Experts have examined the bridge ___ six months.\"(接一段时间用哪个词)","options":["since","at","ago","for"],"answer_index":3,"stem_cn":"专家考察这座桥有六个月了。","explanation_cn":"接“一段时间(six months)”用 for。✓ Experts have examined the bridge for six months. ✗ since:接时间点;✗ ago:用在“时段+ago”结构末尾;✗ at:接钟点。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp4','choice','{"stem":"\"The bridge has stood here ___ 1850.\"(接时间点用哪个词)","options":["since","for","from","ago"],"answer_index":0,"stem_cn":"这座桥自1850年起就矗立在这里。","explanation_cn":"接“时间点/起点(1850)”用 since。✓ The bridge has stood here since 1850. ✗ for:接时段;✗ ago:用在句末;✗ from:此处固定用 since。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp4','choice','{"stem":"\"''We have been working on it ___ last spring,'' he said.\"(接时间起点用哪个词)","options":["for","since","ago","in"],"answer_index":1,"stem_cn":"“我们从去年春天起就一直在研究它。”","explanation_cn":"接“时间起点(last spring)”用 since。✓ We have been working on it since last spring. ✗ for:接时段;✗ ago:用在句末;✗ in:此处不合。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp5','choice','{"stem":"\"The bridge was built more than 170 years ___.\"(“多久以前”用哪个词)","options":["before","for","since","ago"],"answer_index":3,"stem_cn":"这座桥建于170多年前。","explanation_cn":"“多久以前”用“时段 + ago”。✓ The bridge was built more than 170 years ago. ✗ before:不这样单独接时段表“…前”;✗ since:接时间点;✗ for:接时段但不表“…以前”。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp5','choice','{"stem":"\"The wooden parts ___ with stone long ago.\"(很久前被替换:一般过去被动)","options":["are replaced","were replacing","were replaced","have been replaced"],"answer_index":2,"stem_cn":"木制部分很久以前就被换成了石头。","explanation_cn":"很久前“被替换”,用一般过去的被动 were + 过去分词。✓ The wooden parts were replaced with stone long ago. ✗ have been replaced:现在完成,不配 long ago;✗ are replaced:一般现在;✗ were replacing:进行主动。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp5','choice','{"stem":"\"The bridge ___ many times, yet it still looks the same.\"(修过很多次、延续至今:现在完成被动)","options":["was repairing","had repaired","is repairing","has been repaired"],"answer_index":3,"stem_cn":"这座桥修过很多次,但看起来还是老样子。","explanation_cn":"修过很多次、结果延续至今,用现在完成的被动 has been + 过去分词。✓ The bridge has been repaired many times. ✗ was repairing:过去进行主动;✗ is repairing:现在进行主动;✗ had repaired:过去完成主动。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp6','choice','{"stem":"\"After the repairs, the old bridge is now in good ___.\"(状况用哪个词)","options":["condition","century","structure","section"],"answer_index":0,"stem_cn":"修好后,这座老桥现在状况良好。","explanation_cn":"“状况、状态”用 condition。✓ The old bridge is now in good condition. ✗ century:是“世纪”;✗ structure:是“建筑物”;✗ section:是“部分、切片”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp6','choice','{"stem":"\"The experts studied the ___ design of the bridge.\"(最初的用哪个词)","options":["modern","original","fake","final"],"answer_index":1,"stem_cn":"专家研究了这座桥最初的设计。","explanation_cn":"“最初的、原来的”用 original。✓ the original design of the bridge. ✗ final:是“最后的”;✗ fake:是“假的”;✗ modern:是“现代的”。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',5,'am2_l77_gp6','choice','{"stem":"\"It remains one of the oldest ___ in town.\"(建筑物用哪个词)","options":["structures","centuries","experts","stones"],"answer_index":0,"stem_cn":"它仍是镇上最古老的建筑之一。","explanation_cn":"“建筑物、结构体”用 structure(复数 structures)。✓ one of the oldest structures in town. ✗ experts:是“专家”;✗ stones:是“石头”;✗ centuries:是“世纪”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',6,NULL,'choice','{"stem":"美语里\"人行道\"常说:","options":["foot-path","pavement","walk-road","sidewalk"],"answer_index":3,"explanation_cn":"美语“人行道”说 sidewalk;英式说 pavement。✓ Walk on the sidewalk, not in the road. 走人行道,别走车行道。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',6,NULL,'choice','{"stem":"美语里\"市中心\"常说:","options":["downtown","city centre","central-city","town-middle"],"answer_index":0,"explanation_cn":"美语“市中心”说 downtown;英式说 city centre。✓ The old bridge is downtown. 那座老桥在市中心。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',6,NULL,'choice','{"stem":"examine 的意思是:","options":["建造","出售","拆除","检查,考察"],"answer_index":3,"explanation_cn":"examine = 检查、考察。✓ examine the old bridge 考察这座老桥。\n顺带记:建造 = build;拆除 = pull down;出售 = sell."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',6,NULL,'choice','{"stem":"ancient 的意思是:","options":["古老的","巨大的","崭新的","廉价的"],"answer_index":0,"explanation_cn":"ancient = 古老的。✓ one of the ancient structures 最古老的建筑之一。\n顺带记:崭新的 = brand-new;巨大的 = huge;廉价的 = cheap."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',6,NULL,'choice','{"stem":"replace 的意思是:","options":["修理","替换,取代","丢弃","保留"],"answer_index":1,"explanation_cn":"replace = 替换、取代。✓ replaced with stone 被换成了石头。\n顺带记:保留 = keep;丢弃 = throw away;修理 = repair."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',6,NULL,'choice','{"stem":"structure 的意思是:","options":["广场","河流","结构,建筑物","道路"],"answer_index":2,"explanation_cn":"structure = 结构、建筑物。✓ one of the oldest structures 最古老的建筑之一。\n顺带记:河流 = river;道路 = road;广场 = square."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',7,NULL,'cloze','{"stem":"第 1 空","context":"The old bridge ___1___ in 1850, more than 170 years ago. It ___2___ over the river ever since. Experts ___3___ studying it very carefully. They say its design has remained the same ___4___ centuries.","blank_no":1,"options":["was built","has built","is built","was building"],"answer_index":0,"explanation_cn":"过去某年建成、被建造,用一般过去被动。✓ The old bridge was built in 1850.\n✗ has built:结构不对;✗ is built:一般现在;✗ was building:进行。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',7,NULL,'cloze','{"stem":"第 2 空","context":"The old bridge ___1___ in 1850, more than 170 years ago. It ___2___ over the river ever since. Experts ___3___ studying it very carefully. They say its design has remained the same ___4___ centuries.","blank_no":2,"options":["has stood","stood","is standing","had stood"],"answer_index":0,"explanation_cn":"从建成一直矗立到现在,用现在完成。✓ It has stood over the river ever since.\n✗ stood:一般过去;✗ is standing:进行;✗ had stood:过去完成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',7,NULL,'cloze','{"stem":"第 3 空","context":"The old bridge ___1___ in 1850, more than 170 years ago. It ___2___ over the river ever since. Experts ___3___ studying it very carefully. They say its design has remained the same ___4___ centuries.","blank_no":3,"options":["have been","were","are","had been"],"answer_index":0,"explanation_cn":"“have been studying(一直在研究)”,此处填 have been 构成现在完成进行。✓ Experts have been studying it for six months.\n✗ were:一般过去;✗ are:构不成完成进行;✗ had been:过去完成进行,时间点不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',7,NULL,'cloze','{"stem":"第 4 空","context":"The old bridge ___1___ in 1850, more than 170 years ago. It ___2___ over the river ever since. Experts ___3___ studying it very carefully. They say its design has remained the same ___4___ centuries.","blank_no":4,"options":["for","since","ago","at"],"answer_index":0,"explanation_cn":"接“一段时间(centuries)”用 for。✓ Its design has remained the same for centuries.\n✗ since:接时间点;✗ ago:用在句末;✗ at:接钟点。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',8,NULL,'choice','{"stem":"What have the experts been examining?","options":["An old library","A new office tower","A river dam","The oldest bridge in town"],"answer_index":3,"explanation_cn":"课文说 Experts have been examining the oldest bridge in our town for six months。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',8,NULL,'choice','{"stem":"When was the bridge built?","options":["Last spring","In 1850, more than 170 years ago","In 1950","Only six months ago"],"answer_index":1,"explanation_cn":"课文说 The bridge was built in 1850, more than 170 years ago。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',8,NULL,'choice','{"stem":"What did the experts discover about the original bridge?","options":["It was partly made of wood","It was built by a king","It had no stone at all","It was never finished"],"answer_index":0,"explanation_cn":"课文说 The experts discovered that the original bridge was partly wooden。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',9,NULL,'choice','{"stem":"你想说\"专家们已经对这座桥考察了六个月\"(现在完成进行时,强调持续过程):","options":["Experts are examining the bridge for six months.","Experts have been examining the bridge for six months.","Experts have examined the bridge six months ago.","Experts examined the bridge for six months."],"answer_index":1,"explanation_cn":"从过去一直考察到现在、强调持续过程,用现在完成进行 have been + doing。✓ Experts have been examining the bridge for six months. 场合:说某事“一直做到现在、还在做”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',9,NULL,'choice','{"stem":"你想说\"这座桥自1850年起就矗立在这里\"(现在完成 + since 时间点):","options":["The bridge has stood here for 1850.","The bridge is standing here since 1850.","The bridge stood here since 1850.","The bridge has stood here since 1850."],"answer_index":3,"explanation_cn":"延续到现在用现在完成,时间起点用 since。✓ The bridge has stood here since 1850. 场合:说某物“从某个时间点起一直如此”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',9,NULL,'choice','{"stem":"你想说\"这座桥建于170多年前\"(时段 + ago):","options":["The bridge was built more than 170 years for.","The bridge has been built more than 170 years ago.","The bridge was built more than 170 years ago.","The bridge was built more than 170 years since."],"answer_index":2,"explanation_cn":"“多久以前”用“时段 + ago”,句子用一般过去被动。✓ The bridge was built more than 170 years ago. 场合:说某事“发生在多久以前”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',10,NULL,'choice','{"stem":"examine 的意思是:","options":["建造","出售","拆除","检查,考察"],"answer_index":3,"explanation_cn":"examine = 检查、考察。✓ examine the old bridge 考察这座老桥。\n顺带记:建造 = build;拆除 = pull down;出售 = sell."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',10,NULL,'choice','{"stem":"structure 的意思是:","options":["广场","道路","结构,建筑物","河流"],"answer_index":2,"explanation_cn":"structure = 结构、建筑物。✓ one of the oldest structures 最古老的建筑之一。\n顺带记:河流 = river;道路 = road;广场 = square."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',10,NULL,'choice','{"stem":"\"The bridge ___ in 1850.\"(过去某年建成:一般过去被动)","options":["has been built","was building","is built","was built"],"answer_index":3,"stem_cn":"这座桥建于1850年。","explanation_cn":"过去某年建成、被建造,用一般过去被动。✓ The bridge was built in 1850.\n✗ has been built:不配 in 1850;✗ is built:一般现在;✗ was building:进行。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',10,NULL,'choice','{"stem":"\"Experts ___ the bridge for six months.\"(强调持续过程:现在完成进行)","options":["have examined","have been examining","are examining","examined"],"answer_index":1,"stem_cn":"专家们对这座桥考察了六个月。","explanation_cn":"强调“一直考察、还在进行”,用现在完成进行。✓ Experts have been examining the bridge for six months.\n✗ examined:一般过去;✗ are examining:现在进行;✗ have examined:现在完成,不强调过程。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',10,NULL,'choice','{"stem":"\"The bridge has stood here ___ 1850.\" 空里应填:","options":["ago","for","since","at"],"answer_index":2,"explanation_cn":"接“时间点(1850)”用 since。✓ The bridge has stood here since 1850。for 才接一段时间。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',10,NULL,'choice','{"stem":"\"remain the same\" 的意思是:","options":["被拆掉","保持不变","变得更好","彻底改变"],"answer_index":1,"explanation_cn":"remain the same = 保持不变、依旧一样。✓ The design has remained the same 设计一直没变。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',10,NULL,'choice','{"stem":"Why did the city decide to study the bridge carefully?","options":["Because a new bridge was needed","Because it was going to be torn down","Because cracks recently appeared in the old stone","Because it had been sold"],"answer_index":2,"passage":"Experts have been examining the oldest bridge in our town for six months. The bridge was built in 1850, more than 170 years ago. It has stood over the river since then, and thousands of people have crossed it. Recently, cracks appeared in the old stone, so the city decided to study it carefully. The experts discovered that the original bridge was partly wooden. \"We have been working on this since last spring,\" one expert said. \"We have learned a lot about how it was made.\" The wooden parts were replaced with stone long ago, but the design has remained the same for centuries. The bridge has been repaired many times, yet it still looks almost the same as it did in 1850. Today it remains one of the oldest structures in town — and people have loved it for generations.","explanation_cn":"课文说 Recently, cracks appeared in the old stone, so the city decided to study it carefully。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',10,NULL,'choice','{"stem":"What was surprising about the original bridge?","options":["It was made entirely of glass","Part of it was originally made of wood, later replaced with stone","It was built in a single day","It had never been repaired"],"answer_index":1,"passage":"Experts have been examining the oldest bridge in our town for six months. The bridge was built in 1850, more than 170 years ago. It has stood over the river since then, and thousands of people have crossed it. Recently, cracks appeared in the old stone, so the city decided to study it carefully. The experts discovered that the original bridge was partly wooden. \"We have been working on this since last spring,\" one expert said. \"We have learned a lot about how it was made.\" The wooden parts were replaced with stone long ago, but the design has remained the same for centuries. The bridge has been repaired many times, yet it still looks almost the same as it did in 1850. Today it remains one of the oldest structures in town — and people have loved it for generations.","explanation_cn":"课文说 the original bridge was partly wooden… The wooden parts were replaced with stone long ago。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',10,NULL,'choice','{"stem":"How long have experts been examining the bridge?","options":["For six months","For six years","For sixty years","For six days"],"answer_index":0,"audio":"Experts have been examining the oldest bridge in our town for six months. The bridge was built in 1850, more than 170 years ago. It has stood over the river since then, and thousands of people have crossed it. Recently, cracks appeared in the old stone, so the city decided to study it carefully. The experts discovered that the original bridge was partly wooden. \"We have been working on this since last spring,\" one expert said. \"We have learned a lot about how it was made.\" The wooden parts were replaced with stone long ago, but the design has remained the same for centuries. The bridge has been repaired many times, yet it still looks almost the same as it did in 1850. Today it remains one of the oldest structures in town — and people have loved it for generations.","explanation_cn":"课文说 Experts have been examining the oldest bridge… for six months。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l77',10,NULL,'choice','{"stem":"Is the bridge still standing today?","options":["No — it was torn down","Yes — but only half of it","Yes — it remains one of the oldest structures in town","No — it collapsed last year"],"answer_index":2,"audio":"Experts have been examining the oldest bridge in our town for six months. The bridge was built in 1850, more than 170 years ago. It has stood over the river since then, and thousands of people have crossed it. Recently, cracks appeared in the old stone, so the city decided to study it carefully. The experts discovered that the original bridge was partly wooden. \"We have been working on this since last spring,\" one expert said. \"We have learned a lot about how it was made.\" The wooden parts were replaced with stone long ago, but the design has remained the same for centuries. The bridge has been repaired many times, yet it still looks almost the same as it did in 1850. Today it remains one of the oldest structures in town — and people have loved it for generations.","explanation_cn":"课文说 Today it remains one of the oldest structures in town。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l78',2,10,78,'The Last Game','最后一局','复习 KS6/30/54 冠词 a/an/the 与零冠词(收官包·方案B换情节:戒手机游戏):a/an 泛指首次提及、the 特指、零冠词(泛指复数/不可数/抽象名词)、a→the 指代链的辨析','读完一篇讲屏幕时间的文章后,我下决心戒掉手机游戏。我玩了“最后一局”让自己平静下来,然后整整一周没碰游戏。那一周家人可遭了罪——我脾气暴躁、食欲惊人,一副戒瘾的样子。朋友约我玩,我都努力拒绝。“你有英雄般的意志力,”姐姐打趣道。可到了星期天,我拿起手机“只想看看时间”,一小时后就已经沉迷在一局新游戏里了。所谓“最后一局”,也就那样了。','{"q":"Listen and answer — What did the narrator decide to give up?","options":["Games on the phone","Coffee","Movies","Candy"],"answer_index":0}'::jsonb,'{"title":"复习 KS6/30/54 冠词 a / an / the 与零冠词","intro":"冠词看似小,却处处要选对。本课集中复习:①a / an——泛指,第一次提到、表示“一个”,元音开头的词前用 an(an article、an effort),辅音开头用 a(a game、a hero);②the——特指,上文提过、独一无二、双方都清楚的那一个(the last one、the phone);③零冠词——泛指的复数、不可数或抽象名词前不加冠词(games、willpower);④指代链——第一次 a game,再次提到同一个用 the game。","table":{"headers":["冠词","什么时候用","例子"],"rows":[["a","泛指“一个”,辅音开头词前","a game / a habit / a hero"],["an","泛指“一个”,元音开头词前","an article / an effort / an appetite"],["the","特指:提过的、唯一的、都知道的","the last one / the phone / the week"],["零冠词","泛指复数 / 不可数 / 抽象名词","games / willpower / concentration"]]},"specialRules":[{"rule":"用 a 还是 an,看后面词的读音:元音音开头用 an(an article、an effort、an enormous appetite),辅音音开头用 a(a game、a hero)。","mark":"a / an"},{"rule":"美语“手机”常说 cell phone(英式 mobile phone);“电影”说 movie(英式 film)。本课已按美语写。","mark":"cell phone / movie"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l78',1,NULL,'After reading an article about screen time, I made a big decision. I played one last game on my phone to calm my nerves.','读完一篇讲屏幕时间的文章后,我做了一个重大决定。我在手机上玩了最后一局游戏来让自己平静下来。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l78',2,NULL,'I played that last game with concentration and pleasure — I was sure it would be the last one. For a whole week, I did not touch a single game.','我全神贯注、津津有味地玩了那最后一局——我确信它会是最后一局。整整一周,我一局游戏都没碰。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l78',3,NULL,'During the week, my family suffered terribly. I had all the usual symptoms of someone giving up a habit: a bad temper and an enormous appetite.','那一周里,我的家人可遭了罪。我有着戒掉一个习惯的人所有的常见症状:脾气暴躁、食欲惊人。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l78',4,NULL,'My friends kept offering to play games with me, but I made an effort to say no. "You have the willpower of a hero," my sister joked.','朋友们不停地邀我一起玩游戏,但我努力克制着说不。“你有英雄般的意志力,”我姐姐打趣道。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l78',5,NULL,'Then, on Sunday, I picked up the phone "just to check the time." An hour later, I was deep in a new game. So much for the last one!','然后,星期天,我拿起手机“只是想看看时间”。一小时后,我已经沉迷在一局新游戏里了。所谓的“最后一局”,也就那样了!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
