INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l78_gp3','am2_l78','零冠词(泛指复数/不可数/抽象名词)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l78_gp4','am2_l78','a → the 指代链(再次提及同一个)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l78_gp5','am2_l78','冠词综合辨析(a/an/the/零)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_grammar_points (id,lesson_id,name,body_md) VALUES ('am2_l78_gp6','am2_l78','词汇辨析(promise / willpower / habit)',NULL) ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l78','cell phone','mobile phone','手机;美语 cell phone,英式 mobile phone') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l78','movie','film','电影;美语 movie,英式 film') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l78','apartment','flat','公寓;美语 apartment,英式 flat') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l78','elevator','lift','电梯;美语 elevator,英式 lift') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l78','give up','',NULL,'/ɡɪv ʌp/','I decided to give up games.','我决定戒掉游戏。','She gave up coffee last year.','她去年戒了咖啡。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l78','make a promise','',NULL,'/meɪk ə ˈprɑːmɪs/','I made a promise to stop playing.','我许下承诺不再玩了。','He made a promise and kept it.','他许下承诺并做到了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l78','make an effort','',NULL,'/meɪk ən ˈefərt/','I made an effort to say no.','我努力克制着说不。','Please make an effort to be on time.','请努力做到准时。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l78','so much for','',NULL,'/soʊ mʌtʃ fɔːr/','So much for the last one!','所谓的最后一局,也就那样了!','So much for my early night.','我那个早睡的打算,也就那样了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp1','choice','{"stem":"\"After reading ___ article about screen time, I made a big decision.\"(泛指:首次提及、以元音开头的词前)","options":["the","a","an","不填"],"answer_index":2,"stem_cn":"读完一篇讲屏幕时间的文章后,我做了一个重大决定。","explanation_cn":"第一次提到、表示“一篇”,是泛指;article 以元音音开头,所以用 an。✓ an article about screen time. ✗ a:元音音开头的词前不用 a;✗ the:这里不是特指某篇已知的文章;✗ 不填:单数可数名词前要有冠词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp1','choice','{"stem":"\"I made ___ big decision.\"(泛指:第一次提到、表示一个)","options":["a","不填","an","the"],"answer_index":0,"stem_cn":"我做了一个重大决定。","explanation_cn":"第一次提到、表示“一个”,是泛指;decision 以辅音音开头,用 a。✓ a big decision. ✗ an:辅音音开头的词前不用 an;✗ the:不是特指某个已知的决定;✗ 不填:单数可数名词前要有冠词。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp1','choice','{"stem":"\"It was ___ habit I really wanted to break.\"(泛指:表示一个)","options":["an","a","不填","the"],"answer_index":1,"stem_cn":"那是一个我很想改掉的习惯。","explanation_cn":"第一次提到、表示“一个”习惯,泛指;habit 辅音音开头,用 a。✓ a habit I wanted to break. ✗ an / the / 不填:泛指“一个”辅音音开头词前只用 a。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp1','choice','{"stem":"\"My sister called me ___ hero for trying.\"(泛指:表示一个,辅音开头的词前)","options":["the","an","不填","a"],"answer_index":3,"stem_cn":"我姐姐因为我肯尝试而叫我英雄。","explanation_cn":"表示“一个(英雄)”,泛指;hero 读音以辅音音开头,用 a。✓ called me a hero. ✗ an:元音音开头才用;✗ the / 不填:这里是泛指一个,不是特指。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp2','choice','{"stem":"\"I was sure it would be ___ last one.\"(特指:独一无二的那一个)","options":["an","a","the","不填"],"answer_index":2,"stem_cn":"我确信它会是最后一局。","explanation_cn":"“最后那一局”是独一无二、双方都清楚的那一个,特指,用 the。✓ the last one. ✗ a / an:特指唯一的那个不用 a/an;✗ 不填:要有 the 点明“那一个”。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp2','choice','{"stem":"\"During ___ week, my family suffered terribly.\"(特指:上文提到过的那一周)","options":["不填","a","an","the"],"answer_index":3,"stem_cn":"那一周里,我的家人可遭了罪。","explanation_cn":"上文已经提到“戒一周”,这里回指“那一周”,特指,用 the。✓ during the week. ✗ a / an:回指已提过的那一周不用 a/an;✗ 不填:要有 the 点明“那一周”。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp2','choice','{"stem":"\"On Sunday, I picked up ___ phone again.\"(特指:双方都清楚的那部手机)","options":["the","a","an","不填"],"answer_index":0,"stem_cn":"星期天,我又拿起了手机。","explanation_cn":"“我的那部手机”是说话双方都清楚的那一部,特指,用 the。✓ picked up the phone. ✗ a / an:特指自己那部手机不用 a/an;✗ 不填:要有 the。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp2','choice','{"stem":"\"I had all ___ usual symptoms of giving up a habit.\"(特指:那些惯常的症状)","options":["an","不填","a","the"],"answer_index":3,"stem_cn":"我有着戒掉习惯的人所有的常见症状。","explanation_cn":"“那些惯常的症状”是特指一类固定的表现,配 usual 更显特指,用 the。✓ all the usual symptoms. ✗ a / an:后面是复数 symptoms,不用 a/an;✗ 不填:特指要有 the。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp3','choice','{"stem":"\"I decided to give up ___ games for a week.\"(泛指复数,不加冠词)","options":["the","不填","a","an"],"answer_index":1,"stem_cn":"我决定戒掉游戏一个星期。","explanation_cn":"泛指“游戏”这类东西,用复数且不特指某几款,前面不加冠词。✓ give up games. ✗ a / an:后面是复数不用;✗ the:这里不是特指某几款游戏。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp3','choice','{"stem":"\"___ willpower is very hard to keep.\"(抽象名词,不加冠词)","options":["不填","an","the","a"],"answer_index":0,"stem_cn":"意志力很难坚持。","explanation_cn":"willpower(意志力)是抽象名词,泛泛而谈时前面不加冠词。✓ Willpower is hard to keep. ✗ a / an / the:抽象名词泛指时都不加。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp3','choice','{"stem":"\"My friends kept offering to play ___ games with me.\"(泛指复数,不加冠词)","options":["a","不填","the","an"],"answer_index":1,"stem_cn":"朋友们不停地邀我一起玩游戏。","explanation_cn":"泛指“玩游戏”这件事,games 是泛指复数,前面不加冠词。✓ play games with me. ✗ a / an:复数不用;✗ the:不是特指某几款。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp4','choice','{"stem":"\"An hour later, I started ___ new game on my phone.\"(第一次提及、表示一个)","options":["an","the","a","不填"],"answer_index":2,"stem_cn":"一小时后,我在手机上开了一局新游戏。","explanation_cn":"“一局新游戏”第一次出现,泛指“一个”,new 辅音音开头,用 a。✓ started a new game. ✗ an:元音音开头才用;✗ the:第一次提到、还不是特指;✗ 不填:单数可数名词要有冠词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp4','choice','{"stem":"\"I started a new game, and soon I was deep in ___ game.\"(再次提及同一个,特指)","options":["an","the","a","不填"],"answer_index":1,"stem_cn":"我开了一局新游戏,很快就沉浸在那局游戏里了。","explanation_cn":"上一句已提到“a new game”,这里回指同一局,特指,用 the。✓ deep in the game. ✗ a / an:回指同一个已提过的东西不用 a/an;✗ 不填:回指要有 the。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp5','choice','{"stem":"\"I made ___ effort to say no.\"(表示一个、以元音开头的词前)","options":["an","a","不填","the"],"answer_index":0,"stem_cn":"我努力克制着说不。","explanation_cn":"make ___ effort 表示“努力”;effort 以元音音开头,表示“一次努力”,用 an。✓ made an effort. ✗ a:元音音开头不用 a;✗ the / 不填:这里泛指“一次努力”,不是特指。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp5','choice','{"stem":"\"So much for ___ last one!\"(特指:那唯一的最后一局)","options":["不填","a","an","the"],"answer_index":3,"stem_cn":"所谓的最后一局,也就那样了!","explanation_cn":"“那唯一的最后一局”特指,用 the。✓ so much for the last one. ✗ a / an:特指唯一的那个不用;✗ 不填:要有 the 点明“那一个”。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp6','choice','{"stem":"\"I made a ___ to give up games.\"(承诺、决心用哪个词)","options":["window","promise","ticket","ladder"],"answer_index":1,"stem_cn":"我许下承诺要戒掉游戏。","explanation_cn":"下决心、许下的“承诺”是 promise。✓ made a promise to give up games. ✗ ticket 门票;✗ window 窗户;✗ ladder 梯子。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp6','choice','{"stem":"\"___ is the strength to keep going when it is hard.\"(意志力用哪个词)","options":["Weather","Furniture","Willpower","Luggage"],"answer_index":2,"stem_cn":"意志力是在艰难时坚持下去的力量。","explanation_cn":"在艰难时坚持下去的“意志力”是 willpower。✓ Willpower is the strength to keep going. ✗ weather 天气;✗ furniture 家具;✗ luggage 行李。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',5,'am2_l78_gp6','choice','{"stem":"\"Giving up a bad ___ is never easy.\"(习惯用哪个词)","options":["habit","mirror","ticket","corner"],"answer_index":0,"stem_cn":"戒掉一个坏习惯从来都不容易。","explanation_cn":"长期养成、想改掉的“习惯”是 habit。✓ giving up a bad habit. ✗ corner 角落;✗ mirror 镜子;✗ ticket 门票。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',6,NULL,'choice','{"stem":"美语里\"手机\"更常说:","options":["handy","cell phone","mobile","phone-box"],"answer_index":1,"explanation_cn":"美语“手机”常说 cell phone;英式说 mobile phone。✓ I picked up my cell phone."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',6,NULL,'choice','{"stem":"美语里\"电影\"说:","options":["cinema-piece","film","movie","picture-show"],"answer_index":2,"explanation_cn":"美语“电影”说 movie;英式说 film。✓ We watched a movie."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',6,NULL,'choice','{"stem":"willpower 的意思是:","options":["家具","意志力","天气","行李"],"answer_index":1,"explanation_cn":"willpower = 意志力,坚持不放弃的力量。✓ the willpower of a hero 英雄般的意志力。\n顺带记:天气 = weather;家具 = furniture;行李 = luggage."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',6,NULL,'choice','{"stem":"habit 的意思是:","options":["角落","门票","镜子","习惯"],"answer_index":3,"explanation_cn":"habit = 习惯。✓ giving up a habit 戒掉一个习惯。\n顺带记:角落 = corner;镜子 = mirror;门票 = ticket."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',6,NULL,'choice','{"stem":"appetite 的意思是:","options":["食欲,胃口","脾气","努力","症状"],"answer_index":0,"explanation_cn":"appetite = 食欲、胃口。✓ an enormous appetite 惊人的食欲。\n顺带记:脾气 = temper;症状 = symptom;努力 = effort."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',6,NULL,'choice','{"stem":"promise 的意思是:","options":["神经","承诺","文章","专注"],"answer_index":1,"explanation_cn":"promise = 承诺、保证。✓ I made a promise 我许下承诺。\n顺带记:文章 = article;神经 = nerve;专注 = concentration."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',7,NULL,'cloze','{"stem":"第 1 空","context":"After reading ___1___ article about screen time, I made ___2___ big decision. I was sure it would be ___3___ last game I played. For ___4___ whole week, I did not touch a single game.","blank_no":1,"options":["a","an","the","不填"],"answer_index":1,"explanation_cn":"第一次提到、泛指“一篇”;article 元音音开头,用 an。✓ an article about screen time."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',7,NULL,'cloze','{"stem":"第 2 空","context":"After reading ___1___ article about screen time, I made ___2___ big decision. I was sure it would be ___3___ last game I played. For ___4___ whole week, I did not touch a single game.","blank_no":2,"options":["a","an","the","不填"],"answer_index":0,"explanation_cn":"第一次提到、泛指“一个”;decision 辅音音开头,用 a。✓ a big decision."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',7,NULL,'cloze','{"stem":"第 3 空","context":"After reading ___1___ article about screen time, I made ___2___ big decision. I was sure it would be ___3___ last game I played. For ___4___ whole week, I did not touch a single game.","blank_no":3,"options":["a","an","the","不填"],"answer_index":2,"explanation_cn":"“最后那一局”独一无二、特指,用 the。✓ the last game I played."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',7,NULL,'cloze','{"stem":"第 4 空","context":"After reading ___1___ article about screen time, I made ___2___ big decision. I was sure it would be ___3___ last game I played. For ___4___ whole week, I did not touch a single game.","blank_no":4,"options":["a","an","the","不填"],"answer_index":0,"explanation_cn":"“整整一周”first mention、泛指“一(周)”,week 辅音音开头,用 a。✓ for a whole week."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',8,NULL,'choice','{"stem":"What did the narrator decide to give up?","options":["Eating snacks","Watching movies","Playing games on the phone","Drinking coffee"],"answer_index":2,"explanation_cn":"课文说 I made a big decision… I did not touch a single game——他决定戒掉手机游戏。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',8,NULL,'choice','{"stem":"How long did the narrator last without games?","options":["One year","One week","One day","One month"],"answer_index":1,"explanation_cn":"课文说 For a whole week, I did not touch a single game——他坚持了整整一周。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',8,NULL,'choice','{"stem":"What happened on Sunday?","options":["The narrator picked up the phone and started a new game","The narrator won a prize","The narrator read another article","The narrator threw away the phone"],"answer_index":0,"explanation_cn":"课文说 on Sunday, I picked up the phone… An hour later, I was deep in a new game——星期天他又拿起手机玩了起来。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',9,NULL,'choice','{"stem":"你想说\"我读了一篇文章\"(首次提及、元音开头词前该用哪个冠词):","options":["I read the article.","I read article.","I read an article.","I read a article."],"answer_index":2,"explanation_cn":"第一次提到、泛指“一篇”,article 元音音开头,用 an。✓ I read an article. 场合:说自己读了某篇文章。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',9,NULL,'choice','{"stem":"你想说\"那是最后一局\"(独一无二、特指该用哪个冠词):","options":["It was last one.","It was the last one.","It was a last one.","It was an last one."],"answer_index":1,"explanation_cn":"“最后那一局”独一无二、特指,用 the。✓ It was the last one. 场合:强调那是唯一的、最后的一个。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',9,NULL,'choice','{"stem":"你想说\"我戒掉了打游戏\"(泛指复数、不加冠词):","options":["I gave up games.","I gave up an games.","I gave up the a games.","I gave up a games."],"answer_index":0,"explanation_cn":"泛指“游戏”这类东西、用复数,前面不加冠词。✓ I gave up games. 场合:说戒掉了泛指的某类活动。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',10,NULL,'choice','{"stem":"willpower 的意思是:","options":["意志力","天气","家具","门票"],"answer_index":0,"explanation_cn":"willpower = 意志力。✓ the willpower of a hero 英雄般的意志力。\n顺带记:天气 = weather;家具 = furniture;门票 = ticket."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',10,NULL,'choice','{"stem":"habit 的意思是:","options":["角落","文章","习惯","镜子"],"answer_index":2,"explanation_cn":"habit = 习惯。✓ giving up a habit 戒掉一个习惯。\n顺带记:角落 = corner;镜子 = mirror;文章 = article."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',10,NULL,'choice','{"stem":"\"I made ___ big decision.\"(第一次提到、表示一个)","options":["an","the","不填","a"],"answer_index":3,"stem_cn":"我做了一个重大决定。","explanation_cn":"第一次提到、泛指“一个”;decision 辅音音开头,用 a。✓ a big decision."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',10,NULL,'choice','{"stem":"\"It would be ___ last one.\"(独一无二、特指)","options":["不填","the","a","an"],"answer_index":1,"stem_cn":"那会是最后一局。","explanation_cn":"“最后那一局”独一无二、特指,用 the。✓ the last one."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',10,NULL,'choice','{"stem":"\"make an effort\" 的意思是:","options":["努力","失败","放弃","休息"],"answer_index":0,"explanation_cn":"make an effort = 努力(做某事)。✓ I made an effort to say no. 我努力克制着说不。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',10,NULL,'choice','{"stem":"\"give up\" 的意思是:","options":["继续","加入","放弃,戒掉","捡起"],"answer_index":2,"explanation_cn":"give up = 放弃、戒掉。✓ give up games 戒掉游戏。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',10,NULL,'choice','{"stem":"What did the narrator read before making the decision?","options":["A comic","A map","A cookbook","An article about screen time"],"answer_index":3,"passage":"After reading an article about screen time, I made a big decision. I played one last game on my phone to calm my nerves. I played that last game with concentration and pleasure — I was sure it would be the last one. For a whole week, I did not touch a single game. During the week, my family suffered terribly. I had all the usual symptoms of someone giving up a habit: a bad temper and an enormous appetite. My friends kept offering to play games with me, but I made an effort to say no. \"You have the willpower of a hero,\" my sister joked. Then, on Sunday, I picked up the phone \"just to check the time.\" An hour later, I was deep in a new game. So much for the last one!","explanation_cn":"课文说 After reading an article about screen time, I made a big decision——他读的是一篇讲屏幕时间的文章。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',10,NULL,'choice','{"stem":"What happened an hour after Sunday''s \"quick check\"?","options":["The narrator finished homework","The narrator was deep in a new game","The narrator fell asleep","The narrator called a friend"],"answer_index":1,"passage":"After reading an article about screen time, I made a big decision. I played one last game on my phone to calm my nerves. I played that last game with concentration and pleasure — I was sure it would be the last one. For a whole week, I did not touch a single game. During the week, my family suffered terribly. I had all the usual symptoms of someone giving up a habit: a bad temper and an enormous appetite. My friends kept offering to play games with me, but I made an effort to say no. \"You have the willpower of a hero,\" my sister joked. Then, on Sunday, I picked up the phone \"just to check the time.\" An hour later, I was deep in a new game. So much for the last one!","explanation_cn":"课文说 An hour later, I was deep in a new game——一小时后他已经沉迷在一局新游戏里。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',10,NULL,'choice','{"stem":"What did the narrator give up?","options":["Candy","Movies","Coffee","Games on the phone"],"answer_index":3,"audio":"After reading an article about screen time, I made a big decision. I played one last game on my phone to calm my nerves. I played that last game with concentration and pleasure — I was sure it would be the last one. For a whole week, I did not touch a single game. During the week, my family suffered terribly. I had all the usual symptoms of someone giving up a habit: a bad temper and an enormous appetite. My friends kept offering to play games with me, but I made an effort to say no. \"You have the willpower of a hero,\" my sister joked. Then, on Sunday, I picked up the phone \"just to check the time.\" An hour later, I was deep in a new game. So much for the last one!","explanation_cn":"课文说他决定戒掉、一周没碰的正是手机上的游戏。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l78',10,NULL,'choice','{"stem":"Did the narrator keep the promise?","options":["No — the narrator never even tried","No — the narrator started playing again on Sunday","Yes — for a whole year","Yes — forever"],"answer_index":1,"audio":"After reading an article about screen time, I made a big decision. I played one last game on my phone to calm my nerves. I played that last game with concentration and pleasure — I was sure it would be the last one. For a whole week, I did not touch a single game. During the week, my family suffered terribly. I had all the usual symptoms of someone giving up a habit: a bad temper and an enormous appetite. My friends kept offering to play games with me, but I made an effort to say no. \"You have the willpower of a hero,\" my sister joked. Then, on Sunday, I picked up the phone \"just to check the time.\" An hour later, I was deep in a new game. So much for the last one!","explanation_cn":"课文说 on Sunday… An hour later, I was deep in a new game——他星期天又玩了起来,没能守住承诺。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l79',2,10,79,'A Long Journey Home','漫长的回家路','KS7/31/55 一般过去 vs 过去进行 vs used to/would(教材 L79 Key structures,方案B换情节包):一般过去时讲发生的事(stopped/cleared/arrived/opened)、过去进行时讲当时正发生的背景(were traveling/was raining/was waiting/was sleeping)、used to / would 讲过去的习惯(used to take/would always sit/would tell),以及三者在叙事中的配合','我小时候,一家人每年夏天都坐火车去外婆家。我们总是坐在窗边,看着田野掠过。有一年,我们往北走的途中,火车突然停了。当时雨下得很大,前方一棵树倒在了铁轨上。大家安静地等着,工人们把树清走。我弟弟在睡觉,我却看着雨水顺着玻璃往下流。从前,爸爸总会给我们讲故事打发时间。那天,他聊起了他小时候常坐的那些旅行。几个小时后,火车又开动了,我们终于在夜里到了。我至今还记得,外婆开门时那张多么开心的脸。','{"q":"Listen and answer — Why did the train stop that year?","options":["A tree had fallen across the track","It ran out of fuel","There was a strike","It reached the last station"],"answer_index":0}'::jsonb,'{"title":"KS7/31/55 一般过去 / 过去进行 / used to·would","intro":"讲过去的故事,三种说法配合用:①一般过去时——一件件“发生了”的事(the train stopped / we arrived);②过去进行时——某时“正在发生”的背景(while we were traveling / it was raining);③used to / would——过去“习惯性、反复”做的事(my family used to take the train / we would always sit by the window)。used to 强调“过去常、现在不再”;would 强调“过去反复的动作”(不用于状态)。","table":{"headers":["说法","例子"],"rows":[["一般过去(发生的事)","The train suddenly stopped. / We arrived at night."],["过去进行(正发生的背景)","While we were traveling north… / It was raining hard."],["used to(过去的习惯)","My family used to take the train every summer."],["would(过去反复的动作)","We would always sit by the window."],["三者配合","While we were traveling, the train stopped; dad would tell stories."]]},"specialRules":[{"rule":"美语里“铁路”说 railroad(英式 railway)、“秋天”说 fall(英式 autumn)、“假期”说 vacation(英式 holiday);本课已按美语写。","mark":"railroad/fall"},{"rule":"used to + 动词原形=过去常做(现在不再);would + 动词原形=过去反复的动作。二者都讲过去习惯,但 would 不用于“状态”(说 There used to be…,不说 There would be…)。","mark":"used to / would"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l79',1,NULL,'When I was a child, my family used to take the train to my grandma''s every summer. We would always sit by the window and watch the fields go by.','我小时候,一家人每年夏天都坐火车去外婆家。我们总是坐在窗边,看着田野掠过。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l79',2,NULL,'One year, while we were traveling north, the train suddenly stopped. It was raining hard, and a tree had fallen across the track ahead.','有一年,我们往北走的途中,火车突然停了。当时雨下得很大,前方一棵树倒在了铁轨上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l79',3,NULL,'Everyone was waiting quietly while the workers cleared it away. My little brother was sleeping, but I watched the rain run down the glass.','大家安静地等着,工人们把树清走。我弟弟在睡觉,我却看着雨水顺着玻璃往下流。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l79',4,NULL,'In the old days, my dad would tell us stories to pass the time. That day he told us about the trips he used to take as a boy.','从前,爸爸总会给我们讲故事打发时间。那天,他聊起了他小时候常坐的那些旅行。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l79',5,NULL,'Hours later, the train started again, and we finally arrived at night. I still remember how happy grandma looked when she opened the door.','几个小时后,火车又开动了,我们终于在夜里到了。我至今还记得,外婆开门时那张多么开心的脸。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
