INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l79','railroad','railway','铁路;美语 railroad,英式 railway') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l79','fall','autumn','秋天;美语 fall,英式 autumn') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l79','vacation','holiday','假期;美语 vacation,英式 holiday') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l79','downtown','city centre','市中心;美语 downtown,英式 city centre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l79','used to do','',NULL,'/ˈjuːst tə duː/','My family used to take the train every summer.','我家过去每年夏天都坐火车。','I used to live near the sea.','我过去住在海边。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l79','would always do','',NULL,'/wʊd ˈɔːlweɪz duː/','We would always sit by the window.','我们过去总是坐在窗边。','Grandpa would always sing on the way home.','爷爷过去回家路上总是唱歌。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l79','pass the time','',NULL,'/pæs ðə taɪm/','Dad told stories to pass the time.','爸爸讲故事来打发时间。','We played cards to pass the time.','我们打牌来打发时间。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l79','go by','',NULL,'/ɡoʊ baɪ/','We watched the fields go by.','我们看着田野从窗外掠过。','The years went by quickly.','岁月飞快地流逝。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp1','choice','{"stem":"\"One year, while we were traveling north, the train suddenly ___.\"(stop 的过去式,突然停下)","options":["stopped","had stopped","stops","was stopping"],"answer_index":0,"stem_cn":"有一年,我们往北走的途中,火车突然停了。","explanation_cn":"叙事里“突然发生”的一件事,用一般过去时。✓ the train suddenly stopped. ✗ was stopping:过去进行,表“正在停”不合“突然停”;✗ stops:一般现在;✗ had stopped:过去完成。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp1','choice','{"stem":"\"The workers ___ the fallen tree away.\"(clear 的过去式,清走)","options":["were clearing","cleared","had cleared","clear"],"answer_index":1,"stem_cn":"工人们把倒下的树清走了。","explanation_cn":"“把树清走”是发生并完成的动作,用一般过去时。✓ The workers cleared the tree away. ✗ were clearing:过去进行,强调过程,此处说结果;✗ clear:原形;✗ had cleared:过去完成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp1','choice','{"stem":"\"Hours later, the train ___ again, and we finally arrived at night.\"(start 的过去式)","options":["was starting","had started","starts","started"],"answer_index":3,"stem_cn":"几个小时后,火车又开动了,我们终于在夜里到了。","explanation_cn":"“火车又开动了”是发生的动作,用一般过去时。✓ the train started again. ✗ was starting:过去进行;✗ starts:一般现在;✗ had started:过去完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp2','choice','{"stem":"\"One year, while we ___ north, the train stopped.\"(当时正往北走:过去进行)","options":["travel","traveled","were traveling","had traveled"],"answer_index":2,"stem_cn":"有一年,我们正往北走时,火车停了。","explanation_cn":"“当时正往北走”是背景、正在进行,用过去进行时。✓ while we were traveling north. ✗ traveled:一般过去,不表“正在”;✗ travel:一般现在;✗ had traveled:过去完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp2','choice','{"stem":"\"It ___ hard, and a tree had fallen across the track.\"(当时正下大雨:过去进行)","options":["rains","was raining","had rained","rained"],"answer_index":1,"stem_cn":"当时雨下得很大,一棵树倒在了铁轨上。","explanation_cn":"“当时正下大雨”是背景,用过去进行时。✓ It was raining hard. ✗ rained:一般过去;✗ rains:一般现在;✗ had rained:过去完成。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp2','choice','{"stem":"\"My little brother ___ while I watched the rain.\"(当时正在睡:过去进行)","options":["slept","sleeps","had slept","was sleeping"],"answer_index":3,"stem_cn":"我看着雨的时候,我弟弟正在睡觉。","explanation_cn":"“当时正在睡”是背景,用过去进行时。✓ My little brother was sleeping. ✗ slept:一般过去;✗ sleeps:一般现在;✗ had slept:过去完成。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp3','choice','{"stem":"\"When I was a child, my family ___ take the train every summer.\"(过去常做、现在不再)","options":["would have","use to","used to","are used to"],"answer_index":2,"stem_cn":"我小时候,一家人每年夏天都坐火车。","explanation_cn":"“过去常做、现在不再”用 used to + 动词原形。✓ my family used to take the train every summer. ✗ use to:缺 -d,不是正确形式;✗ are used to:意思是“习惯于”，不同;✗ would have:是另一种结构。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp3','choice','{"stem":"\"That day, dad talked about the trips he ___ take as a boy.\"(过去常做的事)","options":["would be","is used to","uses to","used to"],"answer_index":3,"stem_cn":"那天,爸爸聊起他小时候常坐的那些旅行。","explanation_cn":"“过去常坐的旅行”用 used to + 动词原形。✓ the trips he used to take as a boy. ✗ uses to:形式错;✗ is used to:意思是“习惯于”;✗ would be:此处不合。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp3','choice','{"stem":"\"There ___ be a small station here, but it closed years ago.\"(过去有、现在没了)","options":["used to","was used to","would","is used to"],"answer_index":0,"stem_cn":"这儿以前有个小车站,但多年前就关了。","explanation_cn":"表示“过去有、现在没了”的状态,用 used to(would 不表状态)。✓ There used to be a small station here. ✗ would:不表状态;✗ was used to / is used to:意思是“习惯于”，不同。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp4','choice','{"stem":"\"We ___ always sit by the window and watch the fields go by.\"(过去反复的动作)","options":["used to be","would","are","will"],"answer_index":1,"stem_cn":"我们总是坐在窗边,看着田野掠过。","explanation_cn":"“过去反复、总是”做的动作,用 would + 动词原形。✓ We would always sit by the window. ✗ will:表将来;✗ used to be:结构不合;✗ are:一般现在。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp4','choice','{"stem":"\"In the old days, my dad ___ tell us stories to pass the time.\"(过去反复的动作)","options":["will","is going to","would","was"],"answer_index":2,"stem_cn":"从前,爸爸总会给我们讲故事打发时间。","explanation_cn":"“过去(从前)总会”做的动作,用 would。✓ my dad would tell us stories. ✗ will:将来;✗ is going to:将来打算;✗ was:一般过去,不表“反复总会”。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp4','choice','{"stem":"\"Every summer, grandma ___ wait at the door for us.\"(过去反复的习惯动作)","options":["is used to","was being","will","would"],"answer_index":3,"stem_cn":"每年夏天,奶奶总会在门口等我们。","explanation_cn":"“每年夏天总会”做的反复动作,用 would。✓ grandma would wait at the door. ✗ will:将来;✗ is used to:“习惯于”;✗ was being:进行,不合。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp5','choice','{"stem":"\"While everyone ___ quietly, the workers cleared the track.\"(当时正安静等待:过去进行作背景)","options":["waited","was waiting","used to wait","waits"],"answer_index":1,"stem_cn":"大家安静等待的时候,工人们清理着铁轨。","explanation_cn":"“大家当时正安静等待”是背景,用过去进行时。✓ while everyone was waiting quietly. ✗ waited:一般过去;✗ waits:一般现在;✗ used to wait:过去习惯,不合此处“当时正在”。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp5','choice','{"stem":"\"When the sun came out, grandma ___ the door and smiled.\"(叙事里发生的动作:一般过去)","options":["was opening","opens","opened","would open"],"answer_index":2,"stem_cn":"太阳出来时,奶奶开了门,笑了。","explanation_cn":"“开了门”是叙事里发生的动作,用一般过去时。✓ grandma opened the door and smiled. ✗ was opening:过去进行;✗ would open:过去反复,不合“那一刻开门”;✗ opens:一般现在。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp5','choice','{"stem":"\"As a boy, my dad ___ climb that hill every day, but he can''t now.\"(过去的习惯:现在不再)","options":["was climbing","used to","is used to","climbs"],"answer_index":1,"stem_cn":"爸爸小时候每天都爬那座山,可现在爬不动了。","explanation_cn":"“小时候每天爬、现在不再”用 used to + 原形。✓ my dad used to climb that hill every day. ✗ is used to:“习惯于”;✗ was climbing:过去进行;✗ climbs:一般现在。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp6','choice','{"stem":"\"The train ran along the ___ through the fields.\"(铁轨用哪个词)","options":["river","road","track","path"],"answer_index":2,"stem_cn":"火车沿着铁轨穿过田野。","explanation_cn":"火车行驶的“轨道、铁轨”是 track。✓ The train ran along the track. ✗ road:是“公路”;✗ river:是“河”;✗ path:是“小路”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp6','choice','{"stem":"\"We watched the green ___ go by from the window.\"(田野用哪个词)","options":["buildings","fields","mountains","oceans"],"answer_index":1,"stem_cn":"我们从窗口看着绿色的田野掠过。","explanation_cn":"车窗外掠过的“田野”是 field(复数 fields)。✓ We watched the green fields go by. ✗ oceans:是“海洋”;✗ mountains:是“山”;✗ buildings:是“楼房”。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',5,'am2_l79_gp6','choice','{"stem":"\"Dad told stories to ___ the time on the long trip.\"(打发(时间)用哪个词)","options":["lose","waste","pass","save"],"answer_index":2,"stem_cn":"长途旅行中,爸爸讲故事来打发时间。","explanation_cn":"“打发、消磨(时间)”用 pass the time。✓ Dad told stories to pass the time. ✗ waste:是“浪费”(含贬义);✗ lose:是“丢失”;✗ save:是“节省”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',6,NULL,'choice','{"stem":"美语里\"铁路\"常说:","options":["train-line","iron-road","railway","railroad"],"answer_index":3,"explanation_cn":"美语“铁路”说 railroad;英式说 railway。✓ The old railroad runs through the valley. 那条老铁路穿过山谷。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',6,NULL,'choice','{"stem":"美语里\"秋天\"常说:","options":["cold-season","fall","leaf-time","autumn"],"answer_index":1,"explanation_cn":"美语“秋天”说 fall;英式说 autumn。✓ We visited grandma every fall. 我们每年秋天都去看外婆。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',6,NULL,'choice','{"stem":"journey 的意思是:","options":["旅程","行李","车站","车票"],"answer_index":0,"explanation_cn":"journey = 旅程。✓ a long journey home 漫长的回家路。\n顺带记:车站 = station;车票 = ticket;行李 = luggage."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',6,NULL,'choice','{"stem":"suddenly 的意思是:","options":["安静地","缓慢地","经常","突然"],"answer_index":3,"explanation_cn":"suddenly = 突然。✓ the train suddenly stopped 火车突然停了。\n顺带记:缓慢地 = slowly;安静地 = quietly;经常 = often."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',6,NULL,'choice','{"stem":"remember 的意思是:","options":["想象","记得","怀疑","忘记"],"answer_index":1,"explanation_cn":"remember = 记得。✓ I still remember 我至今还记得。\n顺带记:忘记 = forget;想象 = imagine;怀疑 = doubt."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',6,NULL,'choice','{"stem":"arrive 的意思是:","options":["返回","出发","停留","到达"],"answer_index":3,"explanation_cn":"arrive = 到达。✓ we finally arrived at night 我们终于在夜里到了。\n顺带记:出发 = leave;停留 = stay;返回 = return."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',7,NULL,'cloze','{"stem":"第 1 空","context":"When I was a child, my family ___1___ take the train every summer. One year, while we ___2___ north, the train suddenly ___3___. It ___4___ hard, and a tree had fallen across the track.","blank_no":1,"options":["used to","use to","are used to","would have"],"answer_index":0,"explanation_cn":"“过去常做、现在不再”用 used to + 原形。✓ my family used to take the train every summer.\n✗ use to:形式错;✗ are used to:意思是“习惯于”;✗ would have:另一种结构。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',7,NULL,'cloze','{"stem":"第 2 空","context":"When I was a child, my family ___1___ take the train every summer. One year, while we ___2___ north, the train suddenly ___3___. It ___4___ hard, and a tree had fallen across the track.","blank_no":2,"options":["were traveling","traveled","travel","had traveled"],"answer_index":0,"explanation_cn":"“当时正往北走”是背景,用过去进行。✓ while we were traveling north.\n✗ traveled:一般过去;✗ travel:一般现在;✗ had traveled:过去完成。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',7,NULL,'cloze','{"stem":"第 3 空","context":"When I was a child, my family ___1___ take the train every summer. One year, while we ___2___ north, the train suddenly ___3___. It ___4___ hard, and a tree had fallen across the track.","blank_no":3,"options":["stopped","was stopping","stops","had stopped"],"answer_index":0,"explanation_cn":"“突然停了”是发生的动作,用一般过去。✓ the train suddenly stopped.\n✗ was stopping:过去进行;✗ stops:一般现在;✗ had stopped:过去完成。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',7,NULL,'cloze','{"stem":"第 4 空","context":"When I was a child, my family ___1___ take the train every summer. One year, while we ___2___ north, the train suddenly ___3___. It ___4___ hard, and a tree had fallen across the track.","blank_no":4,"options":["was raining","rained","rains","had rained"],"answer_index":0,"explanation_cn":"“当时正下大雨”是背景,用过去进行。✓ It was raining hard.\n✗ rained:一般过去;✗ rains:一般现在;✗ had rained:过去完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',8,NULL,'choice','{"stem":"How did the family travel to grandma''s every summer?","options":["On foot","By car","By plane","By train — they used to take it every summer"],"answer_index":3,"explanation_cn":"课文说 my family used to take the train to my grandma''s every summer。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',8,NULL,'choice','{"stem":"Why did everyone have to wait on the train that year?","options":["There were no more tickets","A tree had fallen across the track and workers were clearing it","The station was closed","The driver was sick"],"answer_index":1,"explanation_cn":"课文说 a tree had fallen across the track… the workers cleared it away。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',8,NULL,'choice','{"stem":"What did the father do to pass the time?","options":["He read a newspaper","He slept the whole way","He told stories about the trips he used to take as a boy","He argued with the workers"],"answer_index":2,"explanation_cn":"课文说 my dad would tell us stories… he told us about the trips he used to take as a boy。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',9,NULL,'choice','{"stem":"你想说\"我们小时候每年夏天都坐火车\"(过去的习惯,用 used to):","options":["We are used to take the train every summer.","We used to take the train every summer.","We use to take the train every summer.","We were taking the train every summer."],"answer_index":1,"explanation_cn":"“过去常做、现在不再”用 used to + 动词原形。✓ We used to take the train every summer. 场合:回忆“过去常做但现在不做”的事。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',9,NULL,'choice','{"stem":"你想说\"我们正往北走时,火车停了\"(过去进行作背景 + 一般过去):","options":["While we were traveling north, the train stopped.","While we travel north, the train stopped.","While we traveled north, the train was stopping.","While we had traveled north, the train stops."],"answer_index":0,"explanation_cn":"背景用过去进行(were traveling),中途发生的事用一般过去(stopped)。✓ While we were traveling north, the train stopped. 场合:讲“正当…的时候,发生了…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',9,NULL,'choice','{"stem":"你想说\"爸爸(从前)总会给我们讲故事\"(过去反复的动作,用 would):","options":["My dad would telling us stories.","My dad will tell us stories.","My dad would tell us stories.","My dad is telling us stories."],"answer_index":2,"explanation_cn":"“过去反复、总会”做的动作用 would + 动词原形。✓ My dad would tell us stories. 场合:回忆过去反复发生的习惯动作。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',10,NULL,'choice','{"stem":"journey 的意思是:","options":["行李","旅程","车站","车票"],"answer_index":1,"explanation_cn":"journey = 旅程。✓ a long journey home 漫长的回家路。\n顺带记:车站 = station;车票 = ticket;行李 = luggage."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',10,NULL,'choice','{"stem":"arrive 的意思是:","options":["到达","返回","出发","停留"],"answer_index":0,"explanation_cn":"arrive = 到达。✓ we finally arrived 我们终于到了。\n顺带记:出发 = leave;停留 = stay;返回 = return."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',10,NULL,'choice','{"stem":"\"My family ___ take the train every summer.\"(过去的习惯,现在不再)","options":["are used to","used to","would have","use to"],"answer_index":1,"stem_cn":"我家过去每年夏天都坐火车。","explanation_cn":"“过去常做、现在不再”用 used to + 原形。✓ my family used to take the train every summer.\n✗ use to:形式错;✗ are used to:意思是“习惯于”;✗ would have:另一种结构。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',10,NULL,'choice','{"stem":"\"While we ___ north, the train stopped.\"(当时正在进行的背景:过去进行)","options":["traveled","travel","were traveling","had traveled"],"answer_index":2,"stem_cn":"我们正往北走时,火车停了。","explanation_cn":"“当时正往北走”是背景,用过去进行。✓ While we were traveling north, the train stopped.\n✗ traveled:一般过去;✗ travel:一般现在;✗ had traveled:过去完成。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',10,NULL,'choice','{"stem":"\"used to do\" 的意思是:","options":["过去常做(现在不再)","将要做某事","习惯于做某事","正在做某事"],"answer_index":0,"explanation_cn":"used to do = 过去常做某事(如今不再)。注意别和 be used to doing(习惯于做)混淆。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',10,NULL,'choice','{"stem":"\"pass the time\" 的意思是:","options":["浪费金钱","打发时间","错过时间","准时到达"],"answer_index":1,"explanation_cn":"pass the time = 打发、消磨时间。如 Dad told stories to pass the time。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',10,NULL,'choice','{"stem":"Why was everyone waiting quietly on the train?","options":["The train had reached the last stop","The lights had gone out","A tree had fallen across the track and the workers were clearing it away","Everyone was asleep"],"answer_index":2,"passage":"When I was a child, my family used to take the train to my grandma''s every summer. We would always sit by the window and watch the fields go by. One year, while we were traveling north, the train suddenly stopped. It was raining hard, and a tree had fallen across the track ahead. Everyone was waiting quietly while the workers cleared it away. My little brother was sleeping, but I watched the rain run down the glass. In the old days, my dad would tell us stories to pass the time. That day he told us about the trips he used to take as a boy. Hours later, the train started again, and we finally arrived at night. I still remember how happy grandma looked when she opened the door.","explanation_cn":"课文说 a tree had fallen across the track ahead. Everyone was waiting quietly while the workers cleared it away。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',10,NULL,'choice','{"stem":"What does the writer remember most about the trips?","options":["How fast the train went","How much the tickets cost","How crowded the station was","How happy grandma looked when she opened the door"],"answer_index":3,"passage":"When I was a child, my family used to take the train to my grandma''s every summer. We would always sit by the window and watch the fields go by. One year, while we were traveling north, the train suddenly stopped. It was raining hard, and a tree had fallen across the track ahead. Everyone was waiting quietly while the workers cleared it away. My little brother was sleeping, but I watched the rain run down the glass. In the old days, my dad would tell us stories to pass the time. That day he told us about the trips he used to take as a boy. Hours later, the train started again, and we finally arrived at night. I still remember how happy grandma looked when she opened the door.","explanation_cn":"课文说 I still remember how happy grandma looked when she opened the door。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',10,NULL,'choice','{"stem":"What had fallen across the track?","options":["A tree","A rock","A wall","A sign"],"answer_index":0,"audio":"When I was a child, my family used to take the train to my grandma''s every summer. We would always sit by the window and watch the fields go by. One year, while we were traveling north, the train suddenly stopped. It was raining hard, and a tree had fallen across the track ahead. Everyone was waiting quietly while the workers cleared it away. My little brother was sleeping, but I watched the rain run down the glass. In the old days, my dad would tell us stories to pass the time. That day he told us about the trips he used to take as a boy. Hours later, the train started again, and we finally arrived at night. I still remember how happy grandma looked when she opened the door.","explanation_cn":"课文说 a tree had fallen across the track ahead。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l79',10,NULL,'choice','{"stem":"When did the train finally arrive?","options":["Early in the morning","At noon","At night","The next day"],"answer_index":2,"audio":"When I was a child, my family used to take the train to my grandma''s every summer. We would always sit by the window and watch the fields go by. One year, while we were traveling north, the train suddenly stopped. It was raining hard, and a tree had fallen across the track ahead. Everyone was waiting quietly while the workers cleared it away. My little brother was sleeping, but I watched the rain run down the glass. In the old days, my dad would tell us stories to pass the time. That day he told us about the trips he used to take as a boy. Hours later, the train started again, and we finally arrived at night. I still remember how happy grandma looked when she opened the door.","explanation_cn":"课文说 we finally arrived at night。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l80',2,10,80,'The Crystal Palace','水晶宫','KS8/32/56 形容词和副词的比较级和最高级(教材 L80 Key structures):最高级(the most extraordinary / one of the biggest / the most famous)、比较级(easier than / more beautiful than / different from)、同级比较(not as easy as it is today);辅以 SD 带 on 的短语(on display / on show / on foot / on business / on duty / on fire / on purpose / on the whole)','19世纪最不平常的建筑也许要数水晶宫了,它是为1851年的“世界博览会”而建在海德公园的。水晶宫不同于世界上所有其他建筑,因为它是用钢和玻璃建成的。它是有史以来最大的建筑物之一,各个国家的许多人纷纷前来参观。大量商品从世界各地送到了博览会,展出的还有很多机器,其中最奇妙的是史密斯的蒸汽锤。尽管当时旅行不像现在这么容易,但汽船还是把成千上万的参观者从欧洲大陆送过了英吉利海峡。一到英国,火车就把他们送到了水晶宫。参观人数总共600万,博览会的赢利用来建造博物馆和高等学校。后来,水晶宫被移到了伦敦南部。在1936年被焚毁之前,它一直是世界上最著名的建筑物之一。','{"q":"Listen and answer — How many people visited the Great Exhibition of 1851?","options":["Six million in all","About sixty thousand","Around one million","Ten million"],"answer_index":0}'::jsonb,'{"title":"KS8/32/56 比较级和最高级 + on 短语","intro":"形容词/副词的三种比较:①最高级——“最…”,短词加 the -est(the biggest),长词用 the most(the most extraordinary),“最…之一”用 one of the + 最高级 + 复数;②比较级——“更…”,短词加 -er + than(easier than),长词用 more…than(more beautiful than),“与…不同”用 different from;③同级比较——as + 原级 + as(as big as),否定 not as/so…as(not as easy as it is today)。SD:带 on 的短语 on display(展出)、on foot(步行)、on business(出差)、on fire(着火)、on purpose(故意)、on the whole(总的来说)。","table":{"headers":["比较","例子"],"rows":[["最高级 the most / the -est","the most extraordinary building / one of the biggest buildings"],["比较级 -er than / more…than","easier than / more beautiful than"],["different from","different from all other buildings"],["同级 as…as / not as…as","not as easy as it is today"],["on 短语","on display / on foot / on business / on fire / on purpose"]]},"specialRules":[{"rule":"美语里“一楼”说 first floor(英式 ground floor)、“电影”说 movie(英式 film)、“电梯”说 elevator(英式 lift);本课已按美语写。(Crystal Palace / Hyde Park 为伦敦真实史实专名,保留。)","mark":"first floor/movie"},{"rule":"带 on 的固定短语要整组记:on display / on show(展出)、on foot(步行)、on business(出差)、on duty(值班)、on fire(着火)、on purpose(故意)、on the whole(总的来说)。","mark":"phrases with on"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l80',1,NULL,'Perhaps the most extraordinary building of the nineteenth century was the Crystal Palace, which was built in Hyde Park for the Great Exhibition of 1851.','19世纪最不平常的建筑也许要数水晶宫了,它是为1851年的“世界博览会”而建在海德公园的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l80',2,NULL,'The Crystal Palace was different from all other buildings in the world, for it was made of iron and glass. It was one of the biggest buildings of all time and a lot of people from many countries came to see it.','水晶宫不同于世界上所有其他建筑,因为它是用钢和玻璃建成的。它是有史以来最大的建筑物之一,各个国家的许多人纷纷前来参观。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l80',3,NULL,'A great many goods were sent to the exhibition from various parts of the world. There was also a great deal of machinery on display. The most wonderful piece of machinery on show was Nasmyth''s steam hammer.','大量商品从世界各地送到了博览会,展出的还有很多机器,其中最奇妙的是史密斯的蒸汽锤。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l80',4,NULL,'Though in those days, traveling was not as easy as it is today, steam boats carried thousands of visitors across the Channel from Europe. On arriving in England, they were taken to the Crystal Palace by train.','尽管当时旅行不像现在这么容易,但汽船还是把成千上万的参观者从欧洲大陆送过了英吉利海峡。一到英国,火车就把他们送到了水晶宫。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l80',5,NULL,'There were six million visitors in all, and the profits from the exhibition were used to build museums and colleges. Later, the Crystal Palace was moved to South London. It remained one of the most famous buildings in the world until it was burnt down in 1936.','参观人数总共600万,博览会的赢利用来建造博物馆和高等学校。后来,水晶宫被移到了伦敦南部。在1936年被焚毁之前,它一直是世界上最著名的建筑物之一。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l80','palace','/ˈpæləs/','n','宫殿','the Crystal Palace') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
