INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am2_l80','various','/ˈveriəs/','adj','各种各样的','from various parts of the world') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
