INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l80','movie','film','电影;美语 movie,英式 film') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am2_l80','elevator','lift','电梯;美语 elevator,英式 lift') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
