INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l80','on display','',NULL,'/ɑːn dɪˈspleɪ/','There was a great deal of machinery on display.','有大量机器在展出。','The paintings are on display in the hall.','这些画正在大厅里展出。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l80','be made of','',NULL,'/bi meɪd əv/','It was made of iron and glass.','它是用钢和玻璃建成的。','The bridge is made of stone.','这座桥是石头做的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l80','on arriving','',NULL,'/ɑːn əˈraɪvɪŋ/','On arriving in England, they were taken to the palace by train.','一到英国,他们就被火车送到了水晶宫。','On arriving home, she called her mother.','一到家,她就给母亲打了电话。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l80','in all','',NULL,'/ɪn ɔːl/','There were six million visitors in all.','参观人数总共600万。','We spent fifty dollars in all.','我们总共花了50美元。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp1','choice','{"stem":"\"The Crystal Palace was perhaps the ___ extraordinary building of the century.\"(最高级:最不平常的,长词用哪个词)","options":["much","very","most","more"],"answer_index":2,"stem_cn":"水晶宫也许是那个世纪最不平常的建筑。","explanation_cn":"extraordinary 是长词,最高级用 the most + 原级。✓ the most extraordinary building. ✗ more:那是比较级;✗ much / very:不构成最高级。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp1','choice','{"stem":"\"It was one of the ___ buildings of all time.\"(最高级:最大的之一,big 的最高级)","options":["biggest","big","bigger","more big"],"answer_index":0,"stem_cn":"它是有史以来最大的建筑之一。","explanation_cn":"big 是短词,最高级是 the biggest;“最…之一”用 one of the + 最高级。✓ one of the biggest buildings of all time. ✗ bigger:比较级;✗ big:原级;✗ more big:短词不用 more。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp1','choice','{"stem":"\"It remained one of the ___ famous buildings in the world.\"(最高级:最著名的之一)","options":["very","more","much","most"],"answer_index":3,"stem_cn":"它一直是世界上最著名的建筑之一。","explanation_cn":"famous 用 the most 构成最高级。✓ one of the most famous buildings in the world. ✗ more:比较级;✗ very / much:不构成最高级。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp2','choice','{"stem":"\"The Crystal Palace was different ___ all other buildings.\"(“与…不同”配哪个介词)","options":["with","to","from","than"],"answer_index":2,"stem_cn":"水晶宫与所有其他建筑都不同。","explanation_cn":"“与…不同”固定用 different from。✓ different from all other buildings. ✗ than:用于比较级 -er than;✗ to / with:不与 different 搭配(美式英语固定 different from)。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp2','choice','{"stem":"\"Travel today is ___ than it was in 1851.\"(easy 的比较级)","options":["easier","easiest","easy","more easy"],"answer_index":0,"stem_cn":"如今旅行比1851年时更容易。","explanation_cn":"easy 是短词,比较级把 y 变 i 加 -er = easier,后接 than。✓ Travel today is easier than it was in 1851. ✗ easy:原级;✗ easiest:最高级;✗ more easy:短词不用 more。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp2','choice','{"stem":"\"The new museum is ___ beautiful than the old one.\"(长词的比较级用哪个词)","options":["very","more","much","most"],"answer_index":1,"stem_cn":"新博物馆比旧的更漂亮。","explanation_cn":"beautiful 是长词,比较级用 more + 原级 + than。✓ more beautiful than the old one. ✗ most:最高级;✗ very / much:不构成比较级。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp3','choice','{"stem":"\"In those days, traveling was ___ it is today.\"(“不像现在这么容易”,填完整的同级比较结构)","options":["not easy so as","not so easy than","not as easier as","not as easy as"],"answer_index":3,"stem_cn":"那时候旅行不像现在这么容易。","explanation_cn":"“不像…那么…”用 not as + 原级 + as，两个 as 都不能少、也不能换成 than。✓ traveling was not as easy as it is today. ✗ not so easy than:同级比较不用 than;✗ not as easier as:同级比较用原级 easy,不用比较级 easier;✗ not easy so as:词序错。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp3','choice','{"stem":"\"This exhibition hall is ___ a football field.\"(“和…一样大”,填完整的同级比较结构)","options":["as big as","so big as","as bigger as","as big than"],"answer_index":0,"stem_cn":"这个展览大厅和一个足球场一样大。","explanation_cn":"“和…一样…”用 as + 原级 + as。✓ as big as a football field. ✗ so big as:肯定句同级用 as…as,不用 so…as;✗ as bigger as:同级用原级 big,不用比较级;✗ as big than:同级用 as，不用 than。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp3','choice','{"stem":"\"Nothing there was ___ the steam hammer.\"(“和…一样奇妙”,填完整的同级比较结构)","options":["as wonderful than","as more wonderful as","as wonderful as","so wonderful than"],"answer_index":2,"stem_cn":"那里没有什么东西像蒸汽锤那样奇妙。","explanation_cn":"“和…一样…”用 as + 原级 + as。✓ as wonderful as the steam hammer. ✗ so wonderful than / as more wonderful as / as wonderful than:都不是正确的同级比较结构(同级用 as…as + 原级)。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp4','choice','{"stem":"\"There was a great deal of machinery ___ display.\"(展出:配哪个介词)","options":["on","for","at","in"],"answer_index":0,"stem_cn":"有大量机器在展出。","explanation_cn":"“展出、陈列”固定用 on display。✓ machinery on display. ✗ in / at / for:都不与 display 搭配表“展出”。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp4','choice','{"stem":"\"I didn''t catch the bus; I came here ___ foot.\"(步行:配哪个介词)","options":["in","on","with","by"],"answer_index":1,"stem_cn":"我没赶上公交,是走来的。","explanation_cn":"“步行”固定用 on foot。✓ I came here on foot. ✗ by:by 后接交通工具(by bus);✗ in / with:不与 foot 搭配。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp4','choice','{"stem":"\"He has gone to Frankfurt ___ business.\"(出差:配哪个介词)","options":["in","for","on","at"],"answer_index":2,"stem_cn":"他去法兰克福出差了。","explanation_cn":"“出差”固定用 on business。✓ He has gone to Frankfurt on business. ✗ for / in / at:都不与 business 搭配表“出差”。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp5','choice','{"stem":"\"Look at that smoke — the building must be ___ fire!\"(着火:配哪个介词)","options":["with","on","at","in"],"answer_index":1,"stem_cn":"看那烟——那栋楼肯定着火了!","explanation_cn":"“着火”固定用 on fire。✓ The building must be on fire! ✗ in / at / with:都不与 fire 搭配表“着火”。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp5','choice','{"stem":"\"I don''t think it was an accident; he did it ___ purpose.\"(故意:配哪个介词)","options":["on","for","by","with"],"answer_index":0,"stem_cn":"我觉得那不是意外,他是故意的。","explanation_cn":"“故意”固定用 on purpose。✓ He did it on purpose. ✗ by:by accident 才是“偶然”;✗ for / with:不与 purpose 搭配表“故意”。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp5','choice','{"stem":"\"___ the whole, it has been a very successful year.\"(总的来说:配哪个介词)","options":["By","In","On","At"],"answer_index":2,"stem_cn":"总的来说,这是很成功的一年。","explanation_cn":"“总的来说”固定用 on the whole。✓ On the whole, it has been a successful year. ✗ In / By / At:都不与 the whole 搭配表“总的来说”。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp6','choice','{"stem":"\"The Crystal Palace was extraordinary — it was quite ___.\"(非凡的、出众的用哪个词)","options":["empty","exceptional","ordinary","funny"],"answer_index":1,"stem_cn":"水晶宫非同寻常,相当出众。","explanation_cn":"extraordinary ≈ exceptional(非凡的、出众的)。✓ it was quite exceptional. ✗ funny:是“好笑的”;✗ empty:是“空的”;✗ ordinary:意思相反,是“普通的”。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp6','choice','{"stem":"\"Goods came from ___ parts of the world.\"(各种各样的用哪个词)","options":["equal","empty","single","various"],"answer_index":3,"stem_cn":"商品来自世界各地。","explanation_cn":"“各种各样的”用 various。✓ from various parts of the world. ✗ single:是“单一的”;✗ equal:是“相等的”;✗ empty:是“空的”。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',5,'am2_l80_gp6','choice','{"stem":"\"Museums were built with the ___ from the exhibition.\"(利润、收益用哪个词)","options":["losses","taxes","profits","debts"],"answer_index":2,"stem_cn":"博物馆是用博览会的利润建的。","explanation_cn":"“利润、收益”用 profit(复数 profits)。✓ built with the profits from the exhibition. ✗ losses:是“亏损”;✗ debts:是“债务”;✗ taxes:是“税款”。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',6,NULL,'choice','{"stem":"美语里\"一楼\"常说:","options":["ground floor","level-one","first floor","bottom-floor"],"answer_index":2,"explanation_cn":"美语“一楼”说 first floor;英式说 ground floor。✓ The exhibits are on the first floor. 展品在一楼。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',6,NULL,'choice','{"stem":"美语里\"电影\"常说:","options":["picture-show","screen-play","film","movie"],"answer_index":3,"explanation_cn":"美语“电影”说 movie;英式说 film。✓ We saw a movie about the palace. 我们看了一部关于水晶宫的电影。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',6,NULL,'choice','{"stem":"extraordinary 的意思是:","options":["不平常的,非凡的","古老的","普通的","廉价的"],"answer_index":0,"explanation_cn":"extraordinary = 不平常的、非凡的。✓ the most extraordinary building 最不平常的建筑。\n顺带记:普通的 = ordinary;古老的 = ancient;廉价的 = cheap."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',6,NULL,'choice','{"stem":"machinery 的意思是:","options":["服装","机器(总称)","食品","家具"],"answer_index":1,"explanation_cn":"machinery = 机器(总称,不可数)。✓ a great deal of machinery 大量机器。\n顺带记:家具 = furniture;服装 = clothing;食品 = food."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',6,NULL,'choice','{"stem":"profit 的意思是:","options":["债务","税款","利润","损失"],"answer_index":2,"explanation_cn":"profit = 利润。✓ the profits from the exhibition 博览会的利润。\n顺带记:损失 = loss;债务 = debt;税款 = tax."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',6,NULL,'choice','{"stem":"various 的意思是:","options":["各种各样的","空的","相同的","单一的"],"answer_index":0,"explanation_cn":"various = 各种各样的。✓ various parts of the world 世界各地。\n顺带记:单一的 = single;相同的 = same;空的 = empty."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',7,NULL,'cloze','{"stem":"第 1 空","context":"The Crystal Palace was perhaps the ___1___ extraordinary building of the century. It was different ___2___ all other buildings, for it was made ___3___ iron and glass. It was one of the ___4___ buildings of all time.","blank_no":1,"options":["most","more","very","much"],"answer_index":0,"explanation_cn":"extraordinary 是长词,最高级用 the most。✓ the most extraordinary building.\n✗ more:比较级;✗ very / much:不构成最高级。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',7,NULL,'cloze','{"stem":"第 2 空","context":"The Crystal Palace was perhaps the ___1___ extraordinary building of the century. It was different ___2___ all other buildings, for it was made ___3___ iron and glass. It was one of the ___4___ buildings of all time.","blank_no":2,"options":["from","than","to","with"],"answer_index":0,"explanation_cn":"“与…不同”用 different from。✓ different from all other buildings.\n✗ than:用于比较级;✗ to / with:不与 different 搭配。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',7,NULL,'cloze','{"stem":"第 3 空","context":"The Crystal Palace was perhaps the ___1___ extraordinary building of the century. It was different ___2___ all other buildings, for it was made ___3___ iron and glass. It was one of the ___4___ buildings of all time.","blank_no":3,"options":["of","from","with","by"],"answer_index":0,"explanation_cn":"“由…制成(原料没发生变化)”用 be made of。✓ it was made of iron and glass.\n✗ from:原料变了才用 made from;✗ with / by:不合。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',7,NULL,'cloze','{"stem":"第 4 空","context":"The Crystal Palace was perhaps the ___1___ extraordinary building of the century. It was different ___2___ all other buildings, for it was made ___3___ iron and glass. It was one of the ___4___ buildings of all time.","blank_no":4,"options":["biggest","bigger","big","more big"],"answer_index":0,"explanation_cn":"big 的最高级是 biggest;“最…之一”用 one of the + 最高级。✓ one of the biggest buildings.\n✗ bigger:比较级;✗ big:原级;✗ more big:短词不用 more。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',8,NULL,'choice','{"stem":"What made the Crystal Palace different from all other buildings?","options":["It was made of iron and glass","It was painted bright red","It stood on water","It had no windows"],"answer_index":0,"explanation_cn":"课文说 The Crystal Palace was different from all other buildings… for it was made of iron and glass。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',8,NULL,'choice','{"stem":"What was the most wonderful machine on show?","options":["A weaving loom","A steam train","Nasmyth''s steam hammer","A printing press"],"answer_index":2,"explanation_cn":"课文说 The most wonderful piece of machinery on show was Nasmyth''s steam hammer。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',8,NULL,'choice','{"stem":"How many people visited the Great Exhibition?","options":["About one thousand","Six million in all","Sixty thousand","One hundred million"],"answer_index":1,"explanation_cn":"课文说 There were six million visitors in all。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',9,NULL,'choice','{"stem":"你想说\"水晶宫是那个世纪最不平常的建筑\"(最高级,长词用 the most):","options":["The Crystal Palace was the most extraordinary building of the century.","The Crystal Palace was a very extraordinary building of the century.","The Crystal Palace was the more extraordinary building of the century.","The Crystal Palace was the extraordinariest building of the century."],"answer_index":0,"explanation_cn":"extraordinary 是长词,最高级用 the most + 原级。✓ the most extraordinary building. 场合:说某物“最…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',9,NULL,'choice','{"stem":"你想说\"那时候旅行不像现在这么容易\"(not as … as 同级比较):","options":["In those days, traveling was not so easy than it is today.","In those days, traveling was not easier as it is today.","In those days, traveling was not as easy than it is today.","In those days, traveling was not as easy as it is today."],"answer_index":3,"explanation_cn":"同级比较的否定用 not as + 原级 + as。✓ not as easy as it is today. 场合:比较两者“不如…那么…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',9,NULL,'choice','{"stem":"你想说\"有大量机器在展出\"(on display):","options":["There was a great deal of machinery at display.","There was a great deal of machinery for display.","There was a great deal of machinery on display.","There was a great deal of machinery in display."],"answer_index":2,"explanation_cn":"“展出”固定用 on display。✓ machinery on display. 场合:说某物正在展出、陈列。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',10,NULL,'choice','{"stem":"extraordinary 的意思是:","options":["不平常的,非凡的","廉价的","普通的","古老的"],"answer_index":0,"explanation_cn":"extraordinary = 不平常的、非凡的。✓ the most extraordinary building 最不平常的建筑。\n顺带记:普通的 = ordinary;古老的 = ancient;廉价的 = cheap."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',10,NULL,'choice','{"stem":"profit 的意思是:","options":["税款","债务","利润","损失"],"answer_index":2,"explanation_cn":"profit = 利润。✓ the profits from the exhibition 博览会的利润。\n顺带记:损失 = loss;债务 = debt;税款 = tax."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',10,NULL,'choice','{"stem":"\"It was one of the ___ buildings of all time.\"(最高级:最大的之一)","options":["biggest","bigger","big","more big"],"answer_index":0,"stem_cn":"它是有史以来最大的建筑之一。","explanation_cn":"big 的最高级是 biggest;“最…之一”用 one of the + 最高级。✓ one of the biggest buildings of all time.\n✗ bigger:比较级;✗ big:原级;✗ more big:短词不用 more。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',10,NULL,'choice','{"stem":"\"Traveling then was ___ it is today.\"(“不像现在这么容易”,填完整的同级比较结构)","options":["not so easy than","not as easy as","not as easier as","not easy so as"],"answer_index":1,"stem_cn":"那时旅行不像现在这么容易。","explanation_cn":"同级比较的否定用 not as + 原级 + as,两个 as 都要有。✓ traveling then was not as easy as it is today.\n✗ not so easy than:不用 than;✗ not as easier as:用原级不用比较级;✗ not easy so as:词序错。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',10,NULL,'choice','{"stem":"\"on display\" 的意思是:","options":["在休息","在维修","在出售","在展出、陈列着"],"answer_index":3,"explanation_cn":"on display = 在展出、陈列着。如 machinery on display 展出的机器。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',10,NULL,'choice','{"stem":"\"on purpose\" 的意思是:","options":["偶然地","故意地","免费地","顺便地"],"answer_index":1,"explanation_cn":"on purpose = 故意地(≠ by accident 偶然地)。如 He did it on purpose 他是故意的。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',10,NULL,'choice','{"stem":"Why was the Crystal Palace different from all other buildings?","options":["Because it had no doors","Because it floated on the river","Because it was made of iron and glass","Because it was painted gold"],"answer_index":2,"passage":"Perhaps the most extraordinary building of the nineteenth century was the Crystal Palace, which was built in Hyde Park for the Great Exhibition of 1851. The Crystal Palace was different from all other buildings in the world, for it was made of iron and glass. It was one of the biggest buildings of all time and a lot of people from many countries came to see it. A great many goods were sent to the exhibition from various parts of the world. There was also a great deal of machinery on display. The most wonderful piece of machinery on show was Nasmyth''s steam hammer. Though in those days, traveling was not as easy as it is today, steam boats carried thousands of visitors across the Channel from Europe. On arriving in England, they were taken to the Crystal Palace by train. There were six million visitors in all, and the profits from the exhibition were used to build museums and colleges. Later, the Crystal Palace was moved to South London. It remained one of the most famous buildings in the world until it was burnt down in 1936.","explanation_cn":"课文说 The Crystal Palace was different from all other buildings… for it was made of iron and glass。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',10,NULL,'choice','{"stem":"What were the profits from the Great Exhibition used for?","options":["To build museums and colleges","To move the palace abroad","To buy more machinery","To pay the visitors"],"answer_index":0,"passage":"Perhaps the most extraordinary building of the nineteenth century was the Crystal Palace, which was built in Hyde Park for the Great Exhibition of 1851. The Crystal Palace was different from all other buildings in the world, for it was made of iron and glass. It was one of the biggest buildings of all time and a lot of people from many countries came to see it. A great many goods were sent to the exhibition from various parts of the world. There was also a great deal of machinery on display. The most wonderful piece of machinery on show was Nasmyth''s steam hammer. Though in those days, traveling was not as easy as it is today, steam boats carried thousands of visitors across the Channel from Europe. On arriving in England, they were taken to the Crystal Palace by train. There were six million visitors in all, and the profits from the exhibition were used to build museums and colleges. Later, the Crystal Palace was moved to South London. It remained one of the most famous buildings in the world until it was burnt down in 1936.","explanation_cn":"课文说 the profits from the exhibition were used to build museums and colleges。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',10,NULL,'choice','{"stem":"How were most visitors from Europe carried across the Channel?","options":["By airplane","By train","By steam boats","On foot"],"answer_index":2,"audio":"Perhaps the most extraordinary building of the nineteenth century was the Crystal Palace, which was built in Hyde Park for the Great Exhibition of 1851. The Crystal Palace was different from all other buildings in the world, for it was made of iron and glass. It was one of the biggest buildings of all time and a lot of people from many countries came to see it. A great many goods were sent to the exhibition from various parts of the world. There was also a great deal of machinery on display. The most wonderful piece of machinery on show was Nasmyth''s steam hammer. Though in those days, traveling was not as easy as it is today, steam boats carried thousands of visitors across the Channel from Europe. On arriving in England, they were taken to the Crystal Palace by train. There were six million visitors in all, and the profits from the exhibition were used to build museums and colleges. Later, the Crystal Palace was moved to South London. It remained one of the most famous buildings in the world until it was burnt down in 1936.","explanation_cn":"课文说 steam boats carried thousands of visitors across the Channel from Europe。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l80',10,NULL,'choice','{"stem":"What happened to the Crystal Palace in 1936?","options":["It was burnt down","It was made bigger","It was sold abroad","It was rebuilt in stone"],"answer_index":0,"audio":"Perhaps the most extraordinary building of the nineteenth century was the Crystal Palace, which was built in Hyde Park for the Great Exhibition of 1851. The Crystal Palace was different from all other buildings in the world, for it was made of iron and glass. It was one of the biggest buildings of all time and a lot of people from many countries came to see it. A great many goods were sent to the exhibition from various parts of the world. There was also a great deal of machinery on display. The most wonderful piece of machinery on show was Nasmyth''s steam hammer. Though in those days, traveling was not as easy as it is today, steam boats carried thousands of visitors across the Channel from Europe. On arriving in England, they were taken to the Crystal Palace by train. There were six million visitors in all, and the profits from the exhibition were used to build museums and colleges. Later, the Crystal Palace was moved to South London. It remained one of the most famous buildings in the world until it was burnt down in 1936.","explanation_cn":"课文说 It remained one of the most famous buildings in the world until it was burnt down in 1936。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
